// City Brush v35 — Singapore landmark intro cards (info_sg). Data only; read by lm31/lmcard (window.SGCard).
// Fields: k kind, y year, a architect, h height m, fl floors, d description, p parent key (secondary pieces).
// Facts that could not be confirmed were left out on purpose.
Object.assign(window.LM_INFO = window.LM_INFO || {}, {

  // ---------------- Changi / Marina Bay ----------------
  jewel: {k:{zh:"机场综合体", en:"Airport complex"}, y:"2019", a:{zh:"萨夫迪建筑事务所（摩西·萨夫迪）", en:"Safdie Architects (Moshe Safdie)"},
    d:{zh:"星耀樟宜是连接樟宜机场一、二、三号航站楼的玻璃穹顶综合体，2019年开幕，集购物、餐饮、酒店与室内花园于一体。中央的“雨漩涡”从穹顶圆孔倾泻而下，高约40米，是世界最高的室内瀑布，四周是层层叠叠的“森林谷”。",
       en:"Jewel is a glass-domed complex linking Terminals 1, 2 and 3 of Changi Airport, opened in 2019 with shops, restaurants, a hotel and indoor gardens. At its centre the Rain Vortex falls about 40 metres through an opening in the roof, the tallest indoor waterfall in the world, surrounded by the terraced Forest Valley."}},
  changitower: {k:{zh:"机场控制塔", en:"Air traffic control tower"},
    d:{zh:"樟宜机场控制塔矗立在一号航站楼旁，自1981年机场启用以来就是樟宜最醒目的标志之一。塔顶的玻璃管制室视野覆盖跑道和滑行道，空中交通管制员在这里指挥航班起降，是这座繁忙国际枢纽的“指挥台”。",
       en:"The control tower stands beside Terminal 1 and has been one of Changi's best-known landmarks since the airport opened in 1981. From the glass cab at the top, air traffic controllers watch the runways and taxiways and guide aircraft in and out of one of the world's busiest international hubs."}},
  esplanade: {k:{zh:"表演艺术中心", en:"Performing arts centre"}, y:"2002", a:{zh:"DP建筑师事务所与迈克尔·威尔福德事务所", en:"DP Architects with Michael Wilford & Partners"},
    d:{zh:"滨海艺术中心于2002年开幕，是新加坡的国家级表演艺术中心，设有音乐厅、剧院、户外剧场和多个小型场地。两座圆壳屋顶覆盖着数千块三角形铝制遮阳板，外形酷似热带水果榴梿，因此常被昵称为“榴梿”。",
       en:"Opened in 2002, the Esplanade is Singapore's national centre for the performing arts, with a concert hall, a theatre, an outdoor stage and smaller studios. Its two rounded roofs are covered with thousands of triangular aluminium sunshades, which make them look like the spiky durian fruit, the nickname everyone uses."}},
  fullerton: {k:{zh:"历史建筑 · 酒店", en:"Historic building, hotel"}, y:"1928", a:{zh:"Keys & Dowdeswell 建筑事务所", en:"Keys & Dowdeswell"},
    d:{zh:"富丽敦大厦建于1928年，以海峡殖民地首任总督罗伯特·富勒顿命名，曾是邮政总局所在地，也容纳过多个政府部门。这座新古典主义建筑以高大的多立克柱廊闻名，2001年改建为富丽敦酒店，2015年被列为国家古迹。",
       en:"Completed in 1928 and named after Robert Fullerton, the first Governor of the Straits Settlements, this building housed the General Post Office and several government offices. Its grand Doric colonnade made it a waterfront landmark. It reopened as The Fullerton Hotel in 2001 and became a National Monument in 2015."}},
  flyer: {k:{zh:"观景摩天轮", en:"Observation wheel"}, y:"2008", h:165, a:{zh:"黑川纪章与DP建筑师事务所", en:"Kisho Kurokawa with DP Architects"},
    d:{zh:"新加坡摩天观景轮高165米，2008年启用，建成时是世界最高的摩天轮。28个空调座舱转一圈约需30分钟，天气晴朗时可远眺滨海湾和新加坡海峡，甚至望见马来西亚和印尼的部分地区。",
       en:"At 165 metres, the Singapore Flyer was the world's tallest observation wheel when it opened in 2008. Its 28 air-conditioned capsules take about 30 minutes for one turn, and on a clear day riders can see across Marina Bay and the Singapore Strait to parts of Malaysia and Indonesia."}},
  helix: {k:{zh:"人行桥", en:"Footbridge"}, y:"2010", a:{zh:"Cox建筑事务所、Architects 61 与奥雅纳", en:"Cox Architecture, Architects 61 and Arup"},
    d:{zh:"双螺旋桥是一座长约280米的人行桥，连接滨海中心与滨海湾金沙，2010年启用。桥身由两条相互缠绕的钢管螺旋构成，灵感来自DNA的双螺旋结构；夜里灯光会照亮桥上代表四种碱基的字母c、g、a、t。",
       en:"The Helix is a 280-metre footbridge between Marina Centre and Marina Bay Sands, opened in 2010. Two steel spirals wind around each other like the double helix of DNA, and at night lights pick out the letters c, g, a and t, the four bases of DNA, along the walkway."}},
  merlion: {k:{zh:"雕塑 · 公园", en:"Statue and park"}, y:"1972", h:8.6, a:{zh:"林浪新（雕塑）、弗雷泽-布伦纳（造型）", en:"Lim Nang Seng (sculptor), Alec Fraser-Brunner (design)"},
    d:{zh:"鱼尾狮是新加坡最著名的象征：狮头呼应古名“新加坡拉”（狮城），鱼身代表这里作为渔村的起源。这座高8.6米的雕像由林浪新雕塑，1972年揭幕，2002年随滨海湾的建设迁到现址，日夜向海湾喷水。",
       en:"The Merlion is Singapore's best-known symbol: the lion's head recalls the old name Singapura, the 'lion city', and the fish body its beginnings as a fishing village. The 8.6-metre statue by Lim Nang Seng was unveiled in 1972 and moved to this spot in 2002, where it spouts water into Marina Bay."}},
  barrage: {k:{zh:"水坝 · 水库", en:"Dam and reservoir"}, y:"2008",
    d:{zh:"滨海堤坝于2008年落成，横跨滨海水道出海口，把海湾变成了位于市中心的淡水水库。它兼具蓄水、防洪和稳定水位三项功能，大雨又逢涨潮时可开闸或抽水排入大海。绿草如茵的屋顶是市民放风筝和野餐的好去处。",
       en:"Completed in 2008, the Marina Barrage dams the mouth of the Marina Channel and turned the bay into a freshwater reservoir in the heart of the city. It stores water, protects low-lying areas from floods and keeps the water level steady. Its grassy green roof is a popular spot for kite-flying and picnics."}},
  mbs: {k:{zh:"综合度假村", en:"Integrated resort"}, y:"2010", a:{zh:"萨夫迪建筑事务所（摩西·萨夫迪）", en:"Safdie Architects (Moshe Safdie)"},
    d:{zh:"滨海湾金沙于2010年开幕，三座酒店塔楼的顶部由长约340米的“金沙空中花园”相连。度假村内有酒店、会展中心、购物中心、剧院和赌场；空中花园上的无边泳池是新加坡天际线最具辨识度的画面之一。",
       en:"Marina Bay Sands opened in 2010 with three hotel towers joined at the top by the SkyPark, a platform about 340 metres long designed by Moshe Safdie. The resort includes a hotel, a convention centre, a mall, theatres and a casino, and the infinity pool on the roof has become one of the most recognisable views of Singapore."}},
  float: {k:{zh:"浮动舞台", en:"Floating stage"}, y:"2007",
    d:{zh:"滨海湾浮动舞台于2007年启用，是一座漂浮在海湾上的大型钢结构舞台，正对岸边的阶梯看台。旧国家体育场重建期间，这里多次举办国庆庆典，看台也用于新加坡F1大奖赛。其所在地已被规划为纪念国民服役的“国民服役广场”。",
       en:"Opened in 2007, The Float is a huge steel stage floating on Marina Bay, facing a stepped grandstand on the shore. While the old National Stadium was being rebuilt it hosted several National Day Parades, and the grandstand is also used during the Singapore Grand Prix. The site has been chosen for NS Square, a new space honouring National Service."}},
  artscience: {k:{zh:"博物馆", en:"Museum"}, y:"2011", a:{zh:"萨夫迪建筑事务所（摩西·萨夫迪）", en:"Safdie Architects (Moshe Safdie)"},
    d:{zh:"艺术科学博物馆于2011年开幕，外形像一朵盛开的莲花，也有人说像张开的手掌，十片“花瓣”伸向天空。屋顶会收集雨水，经中央的开口流入室内水池。馆内展览聚焦艺术、科学与科技的交汇。",
       en:"Opened in 2011, the ArtScience Museum is shaped like a lotus flower, though some see an open hand, with ten 'petals' reaching for the sky. The roof collects rainwater and lets it fall through a central opening into a pool inside. Its exhibitions explore where art, science and technology meet."}},
  mbfc: {k:{zh:"办公与住宅综合体", en:"Office and residential complex"}, y:"2010–2012", h:245, a:{zh:"KPF建筑事务所与Architects 61", en:"Kohn Pedersen Fox with Architects 61"},
    d:{zh:"滨海湾金融中心由三座办公塔楼、两座住宅楼和地下商场组成，于2010至2012年间陆续落成，是把中央商务区延伸到滨海湾填海地的关键项目。最高的塔楼约245米，星展银行等多家金融机构的总部设在这里。",
       en:"Marina Bay Financial Centre brings together three office towers, two residential towers and an underground mall, completed in stages between 2010 and 2012. It was a key step in extending the business district onto reclaimed land at Marina Bay. The tallest tower is about 245 metres, and banks such as DBS have their headquarters here."}},
  marinaone: {k:{zh:"综合体", en:"Mixed-use complex"}, h:225, a:{zh:"英恩霍文建筑事务所", en:"ingenhoven architects"},
    d:{zh:"滨海盛景由两座办公楼和两座住宅楼围合而成，中间是层层叠叠、种满热带植物的“绿心”花园。项目由新加坡和马来西亚的国家投资机构合资开发，源自两国就旧马来亚铁路土地达成的协议，2010年代后期落成。",
       en:"Marina One is made up of two office towers and two residential towers wrapped around the 'Green Heart', a multi-level garden full of tropical plants. It was developed jointly by Singapore and Malaysian state investors, an outcome of the two countries' agreement over the old Malayan Railway land, and was finished in the late 2010s."}},

  // ---------------- CBD / Raffles Place / Tanjong Pagar ----------------
  guoco: {k:{zh:"摩天大楼", en:"Skyscraper"}, y:"2016", h:290, a:{zh:"SOM建筑事务所", en:"Skidmore, Owings & Merrill"},
    d:{zh:"国浩大厦高约290米，2016年落成，是新加坡最高的建筑。它建在丹戎巴葛地铁站上方，集办公、住宅、酒店与零售于一体，脚下还有一片开阔的城市公园，由美国SOM建筑事务所设计。",
       en:"Completed in 2016, Guoco Tower rises about 290 metres and is Singapore's tallest building. Built above Tanjong Pagar MRT station, it combines offices, homes, a hotel and shops, with a large urban park at its foot. It was designed by Skidmore, Owings & Merrill."}},
  oneraffles: {k:{zh:"摩天大楼", en:"Skyscraper"}, y:"1986", h:280, fl:63, a:{zh:"丹下健三", en:"Kenzo Tange"},
    d:{zh:"莱佛士坊一号原名华联银行中心，1986年落成，由日本建筑师丹下健三设计。高280米的塔楼由两个三角形体块组合而成，多年来与大华银行广场、共和大厦并列为新加坡最高的建筑。",
       en:"Formerly the OUB Centre, One Raffles Place was completed in 1986 to a design by Japanese architect Kenzo Tange. Its 280-metre tower is made of two triangular blocks, and for many years it shared the title of Singapore's tallest building with UOB Plaza One and Republic Plaza."}},
  uob: {k:{zh:"摩天大楼", en:"Skyscraper"}, h:280, a:{zh:"丹下健三", en:"Kenzo Tange"},
    d:{zh:"大华银行广场是大华银行的总部，主楼高280米，同样由丹下健三设计，于1990年代建成。塔身由几组相互错开45度的八角形体块叠加而成；临河的广场上摆放着哥伦比亚艺术家博特罗的雕塑《鸟》等艺术品。",
       en:"UOB Plaza is the headquarters of United Overseas Bank. Its main tower, 280 metres tall and also designed by Kenzo Tange, was finished in the 1990s and is built up from octagonal blocks turned 45 degrees to each other. The riverside plaza displays artworks such as Fernando Botero's sculpture 'Bird'."}},
  republic: {k:{zh:"摩天大楼", en:"Skyscraper"}, h:280, a:{zh:"黑川纪章", en:"Kisho Kurokawa"},
    d:{zh:"共和大厦高280米，由日本建筑师黑川纪章设计，于1990年代建成。它与莱佛士坊一号、大华银行广场长期并列为新加坡最高的建筑——三座大楼都建到了为保障航空安全而设定的高度上限。",
       en:"Republic Plaza, designed by Japanese architect Kisho Kurokawa and built in the 1990s, rises 280 metres. Together with One Raffles Place and UOB Plaza One it long shared the title of Singapore's tallest building; all three were built right up to the height limit set for aircraft safety."}},
  lauPaSat: {k:{zh:"历史市场 · 小贩中心", en:"Historic market, food centre"}, y:"1894", a:{zh:"詹姆斯·麦克里奇", en:"James MacRitchie"},
    d:{zh:"老巴刹原名直落亚逸巴刹，现存的八角形铸铁建筑于1894年落成，铁构件在苏格兰格拉斯哥铸造后运来组装。1980年代修建地铁时，整座建筑曾被逐件拆下、编号，再原样装回。如今这里是热闹的小贩中心，入夜后旁边的街道会变成沙爹街。",
       en:"Lau Pa Sat, once called Telok Ayer Market, is an octagonal cast-iron market hall finished in 1894; its ironwork was made in Glasgow and shipped out. When the MRT was built in the 1980s, the whole structure was taken apart piece by piece and put back again. Today it is a busy food centre, and at night the street beside it turns into Satay Street."}},
  capitaspring: {k:{zh:"摩天大楼", en:"Skyscraper"}, y:"2021", h:280, fl:51, a:{zh:"BIG建筑事务所与卡洛·拉蒂事务所", en:"BIG with Carlo Ratti Associati"},
    d:{zh:"凯德·春高280米，2021年落成。塔楼中段打开成一个螺旋上升、跨越数层的“绿洲”空中花园，楼顶还有一座空中花园；原址上的小贩中心也在塔楼底部重建。",
       en:"CapitaSpring, completed in 2021, is a 280-metre tower by BIG and Carlo Ratti Associati. Its middle opens up into the Green Oasis, a garden spiralling through several floors, and there is another garden on the roof. The hawker centre that stood on the site was rebuilt at the tower's base."}},
  parkroyal: {k:{zh:"酒店", en:"Hotel"}, y:"2013", a:{zh:"WOHA建筑事务所", en:"WOHA"},
    d:{zh:"芳林皇家公园酒店于2013年开业，由新加坡本土事务所WOHA设计。酒店的空中花园、绿墙和瀑布总面积约为基地面积的两倍，起伏的混凝土裙楼像梯田或山谷，是“花园中的城市”理念的代表作。",
       en:"Opened in 2013, this hotel by Singapore firm WOHA is famous for its sky gardens, green walls and waterfalls, which add up to about twice the area of the site itself. Its wavy concrete podium looks like terraced fields or a valley, making it a showcase of Singapore's 'city in a garden' idea."}},
  pinnacle: {k:{zh:"公共组屋", en:"Public housing"}, y:"2009", fl:50, a:{zh:"ARC Studio 建筑事务所", en:"ARC Studio Architecture + Urbanism"},
    d:{zh:"达士岭组屋于2009年落成，七座50层的塔楼由两条空中走廊相连，是新加坡最高的公共组屋。它建在新加坡最早一批组屋的旧址上；第50层的空中花园向访客开放（需购票），可俯瞰市中心与港口。",
       en:"Completed in 2009, Pinnacle@Duxton has seven 50-storey towers linked by two sky bridges, making it Singapore's tallest public housing. It stands on the site of some of the earliest HDB flats. The skygarden on the 50th floor is open to visitors for a small fee and looks out over the city and the port."}},
  interlace: {k:{zh:"住宅", en:"Residential"}, y:"2013", a:{zh:"OMA / 奥雷·舍人", en:"OMA / Ole Scheeren"},
    d:{zh:"翠城新景由31座六层高的公寓楼像积木一样，以六边形格局交错叠放而成，围出多个开阔的庭院和屋顶花园。项目于2013年落成，2015年获得世界建筑节“年度世界建筑”大奖。",
       en:"The Interlace is made of 31 six-storey apartment blocks stacked across each other like building blocks in a hexagonal pattern, creating large open courtyards and roof gardens. It was completed in 2013 and named World Building of the Year at the World Architecture Festival in 2015."}},

  // ---------------- Civic District ----------------
  raffleshotel: {k:{zh:"历史酒店", en:"Historic hotel"}, y:"1887", a:{zh:"斯旺与麦克拉伦（1899年主楼）", en:"Swan & Maclaren (1899 main building)"},
    d:{zh:"莱佛士酒店由亚美尼亚裔的萨基斯兄弟于1887年创办，以新加坡开埠者莱佛士命名。白色的殖民地风格主楼建于1899年，酒店的长吧被认为是鸡尾酒“新加坡司令”的诞生地。酒店于1987年被列为国家古迹。",
       en:"Raffles Hotel was founded in 1887 by the Armenian Sarkies brothers and named after Stamford Raffles. The white colonial main building dates from 1899, and the hotel's Long Bar is known as the birthplace of the Singapore Sling cocktail. It was made a National Monument in 1987."}},
  natgallery: {k:{zh:"美术馆", en:"Art museum"}, y:"2015", a:{zh:"studioMilou 与 CPG 顾问公司（改建）", en:"studioMilou with CPG Consultants (conversion)"},
    d:{zh:"新加坡国家美术馆于2015年开馆，由前最高法院大厦和政府大厦两座国家古迹改建而成，以新的金属顶棚相连。这里收藏着世界上规模最大的新加坡与东南亚近现代艺术公共收藏。政府大厦也是1945年日军签署投降书的地方。",
       en:"National Gallery Singapore opened in 2015 inside two National Monuments, the former Supreme Court and City Hall, linked by a new canopy roof. It holds the world's largest public collection of modern art from Singapore and Southeast Asia. City Hall is also where the Japanese surrender was signed in 1945."}},
  supremecourt: {k:{zh:"法院", en:"Law courts"}, y:"2005", a:{zh:"福斯特建筑事务所", en:"Foster + Partners"},
    d:{zh:"新加坡最高法院新大楼于2005年启用，由英国福斯特建筑事务所设计。最醒目的是楼顶那座圆盘形结构，里面是上诉庭，寓意司法的公正与透明；高层还设有可俯瞰巴东草场和市区的观景处。",
       en:"The new Supreme Court building opened in 2005, designed by Foster + Partners. Its most striking feature is the disc on top, which houses the Court of Appeal and is meant to suggest the fairness and openness of justice. A viewing area near the top looks over the Padang and the city."}},
  victoria: {k:{zh:"剧院 · 音乐厅", en:"Theatre and concert hall"}, y:"1862 / 1905",
    d:{zh:"这组建筑由1862年建成的市政厅（今维多利亚剧院）和1905年为纪念维多利亚女王而建的纪念堂（今音乐会堂）组成，两者之间的钟楼是市中心的标志。音乐会堂是新加坡交响乐团的大本营，2014年完成大规模修复后重新开放。",
       en:"This pair of buildings joins the old Town Hall of 1862, now Victoria Theatre, and the Victoria Memorial Hall of 1905, built in memory of Queen Victoria, now the Concert Hall. The clock tower between them is a city landmark. The Concert Hall is home to the Singapore Symphony Orchestra and reopened in 2014 after a major restoration."}},
  standrews: {k:{zh:"圣公会座堂", en:"Anglican cathedral"}, y:"1856–1861", a:{zh:"罗纳德·麦弗森上校", en:"Col. Ronald MacPherson"},
    d:{zh:"圣安德烈座堂是新加坡最大的圣公会座堂，现今的新哥特式建筑由印度囚犯劳工在1856至1861年间建成。墙面抹的是“马德拉斯灰泥”，由贝壳灰、蛋白、糖和椰壳纤维调成，因而洁白光亮。教堂于1973年被列为国家古迹。",
       en:"St Andrew's Cathedral is Singapore's largest Anglican cathedral. The present Neo-Gothic church was built by Indian convict labourers between 1856 and 1861. Its walls are finished with 'Madras chunam', a plaster of shell lime, egg white, sugar and coconut husk that gives them a bright white sheen. It became a National Monument in 1973."}},
  chijmes: {k:{zh:"历史建筑群", en:"Historic complex"}, y:"1840s–1904",
    d:{zh:"赞美广场原是圣婴女修道院，最早的考德威尔楼建于1840年代，哥特式礼拜堂于1904年落成，彩色玻璃窗十分精美。修道院曾收留被遗弃的婴儿，围墙上的“希望之门”就是人们放下婴儿的地方。1990年代修复后成为餐饮与活动场所。",
       en:"CHIJMES was once the Convent of the Holy Infant Jesus. Its oldest building, Caldwell House, dates from the 1840s, and the Gothic chapel with its fine stained glass was finished in 1904. The convent took in abandoned babies, often left at the 'Gate of Hope' in its wall. After restoration in the 1990s it became a place for dining and events."}},
  natmuseum: {k:{zh:"博物馆", en:"Museum"}, y:"1887",
    d:{zh:"新加坡国家博物馆是新加坡历史最悠久的博物馆，前身莱佛士图书馆与博物馆可追溯至1849年。现存的新古典主义主楼于1887年落成，白色圆顶下镶着彩色玻璃；2006年又增建了现代玻璃翼楼。馆内主要讲述新加坡的历史。",
       en:"The National Museum is Singapore's oldest museum, tracing its roots to the Raffles Library and Museum of 1849. The neoclassical main building, with its white dome and stained glass, opened in 1887, and a modern glass wing was added in 2006. Its galleries tell the story of Singapore's history."}},
  hillstreet: {k:{zh:"历史建筑 · 政府办公楼", en:"Historic building, government offices"}, y:"1934",
    d:{zh:"旧禧街警察局建于1934年，曾是警察局和警员及家属的宿舍。外墙上九百多扇窗户的百叶窗被漆成彩虹般的鲜艳颜色，是新加坡河畔最上镜的建筑之一。它于1998年被列为国家古迹，现为政府部门的办公楼。",
       en:"Built in 1934, the Old Hill Street Police Station once held a police station and quarters for officers and their families. More than 900 window shutters are painted in rainbow colours, making it one of the most photographed buildings by the Singapore River. It became a National Monument in 1998 and now houses government ministries."}},
  acm: {k:{zh:"博物馆", en:"Museum"}, y:"1867",
    d:{zh:"亚洲文明博物馆设在皇后坊大厦内。这座新古典主义建筑于1867年作为法院落成，后来由多个政府部门使用，名字取自维多利亚女王的“印度女皇”称号。博物馆展示亚洲各地文化的交流，馆藏亮点包括九世纪唐代沉船出水的珍宝。",
       en:"The Asian Civilisations Museum is housed in the Empress Place Building, a neoclassical block completed as a courthouse in 1867 and later used by government offices; the name honours Queen Victoria as Empress of India. The museum explores links between Asian cultures, and its highlights include treasures from a ninth-century Tang dynasty shipwreck."}},
  parkview: {k:{zh:"办公大楼", en:"Office building"}, y:"2002", a:{zh:"詹姆斯·亚当斯与DP建筑师事务所", en:"James Adams with DP Architects"},
    d:{zh:"百汇广场于2002年落成，模仿1920年代纽约的装饰艺术风格，深色外墙、铜色装饰和塔顶的雕像让它常被称作“高谭大厦”。大堂的Atlas酒吧有一座三层楼高的杜松子酒塔，广场上还立着孙中山、林肯等历史人物的铜像。",
       en:"Completed in 2002, Parkview Square is styled like a 1920s New York Art Deco skyscraper, with a dark facade, bronze details and statues around its crown; many call it the 'Gotham building'. The lobby bar, Atlas, has a three-storey gin tower, and bronze statues of figures such as Sun Yat-sen and Abraham Lincoln stand in the plaza."}},
  natlibrary: {k:{zh:"图书馆", en:"Library"}, y:"2005", fl:16, a:{zh:"杨经文（T. R. Hamzah & Yeang）", en:"Ken Yeang (T. R. Hamzah & Yeang)"},
    d:{zh:"国家图书馆大厦于2005年在维多利亚街启用，由马来西亚建筑师杨经文设计，以遮阳板、自然通风和空中花园来适应热带气候。它取代了史丹福路上深受市民喜爱的红砖旧馆——旧馆在2004年因修建福康宁隧道而被拆除。",
       en:"The National Library Building on Victoria Street opened in 2005. Designed by Malaysian architect Ken Yeang, it uses sunshades, natural ventilation and sky gardens to suit the tropical climate. It replaced the much-loved red-brick library on Stamford Road, which was pulled down in 2004 to make way for the Fort Canning Tunnel."}},
  duo: {k:{zh:"综合体", en:"Mixed-use towers"}, a:{zh:"奥雷·舍人事务所", en:"Büro Ole Scheeren"},
    d:{zh:"DUO双子塔由德国建筑师奥雷·舍人设计，两座塔楼的立面向内凹进，仿佛被挖去一块，外墙覆盖着蜂窝状的遮阳格。塔楼内有办公、住宅和酒店；它与滨海盛景一样由新马两国合资开发，2010年代后期落成。",
       en:"DUO's twin towers, designed by Ole Scheeren, have concave faces that look as if they have been scooped out, covered in a honeycomb pattern of sunshades. They hold offices, apartments and a hotel. Like Marina One, the project was a Singapore–Malaysia joint venture, completed in the late 2010s."}},
  sggateway: {k:{zh:"办公大楼", en:"Office towers"}, y:"1990", h:150, fl:37, a:{zh:"贝聿铭", en:"I. M. Pei"},
    d:{zh:"门户大厦是两座37层的办公楼，1990年落成，由华裔美国建筑师贝聿铭设计。两座塔楼的平面都是梯形，从某些角度看去薄得像一张纸或一片刀刃，好像只是一个平面，是美芝路上最有趣的视觉错觉。",
       en:"The Gateway is a pair of 37-storey office towers completed in 1990 and designed by I. M. Pei. Each tower has a trapezoid plan, so from certain angles it looks as thin as a sheet of paper or a blade, a striking optical trick on Beach Road."}},
  goldenmile: {k:{zh:"综合大楼", en:"Mixed-use complex"}, y:"1973", a:{zh:"设计伙伴事务所（Design Partnership）", en:"Design Partnership"},
    d:{zh:"黄金坊大厦于1973年落成，由林少伟等本地建筑师创办的设计伙伴事务所设计。阶梯式的退台外形把住宅、办公和商店叠在一栋楼里，是“垂直城市”理念的早期尝试。这里长期被称为“小泰国”，2021年被列为保留建筑。",
       en:"Completed in 1973, Golden Mile Complex was designed by the local firm Design Partnership, whose founders included William Lim. Its stepped, terraced shape stacks homes, offices and shops into one building, an early try at a 'vertical city'. Long known as Singapore's 'Little Thailand', it was gazetted for conservation in 2021."}},
  southbeach: {k:{zh:"综合体", en:"Mixed-use development"}, h:218, a:{zh:"福斯特建筑事务所与Aedas", en:"Foster + Partners with Aedas"},
    d:{zh:"南滩是集办公、酒店、住宅和零售于一体的综合项目，2010年代中期落成。两座弧形塔楼之间覆盖着一片巨大的波浪形顶棚，可遮阳挡雨并引导自然风；原址上的海滩路军营旧建筑也被保留下来并重新利用。",
       en:"South Beach is a mixed development of offices, a hotel, homes and shops, completed in the mid-2010s. A huge wavy canopy between its two curved towers gives shade and shelter and helps channel breezes. Old buildings of the former Beach Road military camp on the site were kept and given new uses."}},
  suntec: {k:{zh:"商业综合体", en:"Office and retail complex"}, y:"1997", h:181, fl:45, a:{zh:"Tsao & McKown 建筑事务所", en:"Tsao & McKown Architects"},
    d:{zh:"新达城由四座45层和一座18层的办公楼组成，从空中俯瞰像一只张开的手，按风水理念布局，掌心正是“财富之泉”。这座喷泉于1998年被吉尼斯世界纪录列为世界最大的喷泉，据说绕泉而行能带来好运。",
       en:"Suntec City has four 45-storey office towers and one 18-storey tower. Seen from above, they are laid out like the fingers of an open hand, following feng shui ideas, with the Fountain of Wealth in the palm. Guinness World Records listed the fountain as the world's largest in 1998, and walking around it is said to bring good luck."}},
  indoorstadium: {k:{zh:"室内体育馆", en:"Indoor arena"}, y:"1989", a:{zh:"丹下健三", en:"Kenzo Tange"},
    d:{zh:"新加坡室内体育馆于1989年启用，由丹下健三设计，屋顶形似亚洲传统建筑上翘的屋檐。场馆可容纳约一万二千名观众，是举办演唱会以及羽毛球、网球等赛事的主要场地，现为新加坡体育城的一部分。",
       en:"Opened in 1989 and designed by Kenzo Tange, the Singapore Indoor Stadium has a roof inspired by the swept-up eaves of traditional Asian buildings. Holding about 12,000 people, it is one of the city's main venues for concerts and for sports such as badminton and tennis, and is now part of the Singapore Sports Hub."}},
  sportshub: {k:{zh:"体育场", en:"Stadium"}, y:"2014", a:{zh:"奥雅纳与DP建筑师事务所", en:"Arup with DP Architects"},
    d:{zh:"新国家体育场于2014年在1973年旧体育场的原址上启用，约有五万五千个座位。它的可开合穹顶跨度约310米，是世界上最大的自由跨度穹顶之一，烈日或下雨时可以关上；看台还装有向座位送冷风的降温系统。",
       en:"The new National Stadium opened in 2014 on the site of the 1973 original, with about 55,000 seats. Its retractable roof spans some 310 metres, one of the largest free-spanning domes in the world, and can close against sun or rain. The stands also have a cooling system that blows cool air near the seats."}},

  // ---------------- Kampong Gelam / Chinatown / Orchard ----------------
  sultanmosque: {k:{zh:"清真寺", en:"Mosque"}, y:"1932", a:{zh:"丹尼斯·桑特里（斯旺与麦克拉伦）", en:"Denis Santry (Swan & Maclaren)"},
    d:{zh:"这里最早的清真寺建于1820年代，为苏丹侯赛因而建；现今的苏丹回教堂由爱尔兰建筑师丹尼斯·桑特里设计，于1932年竣工。金色圆顶的底部环绕着一圈玻璃瓶底，是由贫困的穆斯林收集捐出的，让每个人都能为建寺出一份力。",
       en:"The first mosque here was built in the 1820s for Sultan Hussein Shah. The present building, designed by Irish architect Denis Santry, was completed in 1932. A band of glass bottle ends runs around the base of its golden domes; they were collected and donated by poorer Muslims so that everyone could contribute."}},
  mariamman: {k:{zh:"兴都庙", en:"Hindu temple"}, y:"1827",
    d:{zh:"马里安曼兴都庙由商人纳莱纳·皮莱于1827年创建，是新加坡最古老的兴都庙，供奉以治病消灾著称的马里安曼女神。入口上方的门塔布满色彩缤纷的神像；每年的蹈火节上，信众会赤脚走过炭火坑。",
       en:"Founded in 1827 by the merchant Naraina Pillai, Sri Mariamman is Singapore's oldest Hindu temple, dedicated to the goddess Mariamman, known for curing illness. Its tall entrance tower is covered with brightly painted deities, and every year devotees walk barefoot over hot coals during the Theemithi festival."}},
  buddhatooth: {k:{zh:"佛寺", en:"Buddhist temple"}, y:"2007",
    d:{zh:"佛牙寺龙华院于2007年落成，建筑仿照中国唐代风格，供奉着一颗被认为是佛陀牙舍利的圣物。寺内设有佛教文化博物馆，屋顶花园中有一座大型转经轮。寺院位于牛车水，信众与游客都常来参访。",
       en:"Completed in 2007 in the style of China's Tang dynasty, the Buddha Tooth Relic Temple enshrines what is believed to be a tooth relic of the Buddha. It has a museum of Buddhist culture, and its rooftop garden holds a large prayer wheel. The temple stands in Chinatown and welcomes both worshippers and visitors."}},
  thianhockkeng: {k:{zh:"华人庙宇", en:"Chinese temple"}, y:"1839–1842",
    d:{zh:"天福宫建于1839至1842年间，是新加坡最古老、最重要的福建庙宇之一，主祀海上守护神妈祖。它当年就建在海岸边，南来的移民平安登岸后会到这里上香谢恩。庙宇以传统工艺建造，据说没用一根铁钉，1973年被列为国家古迹。",
       en:"Built between 1839 and 1842, Thian Hock Keng is one of Singapore's oldest and most important Hokkien temples, dedicated to Mazu, goddess of the sea. It once stood on the shoreline, and newly arrived immigrants came here to give thanks for a safe voyage. It was built with traditional methods, reportedly without nails, and became a National Monument in 1973."}},
  peoplespark: {k:{zh:"综合大楼", en:"Mixed-use complex"}, y:"1973", fl:31, a:{zh:"设计伙伴事务所（Design Partnership）", en:"Design Partnership"},
    d:{zh:"珍珠坊于1973年落成，是一座31层的住宅板楼加商场裙楼，也出自设计伙伴事务所。它的商场围绕一个开放的大中庭——设计者称之为“城市客厅”——是区域内最早这样设计的商场之一，深受日本新陈代谢派影响。鲜艳的外墙配色让它成为牛车水的地标。",
       en:"Completed in 1973, People's Park Complex combines a 31-storey residential slab with a shopping podium, another work of Design Partnership. Its mall, built around a large open atrium the designers called a 'city room', was one of the first of its kind in the region and shows the influence of Japan's Metabolist movement. Bold paintwork makes it a Chinatown landmark."}},
  ionorchard: {k:{zh:"购物中心 · 住宅", en:"Mall and residences"}, y:"2009", h:218, a:{zh:"Benoy 与 RSP 建筑事务所", en:"Benoy with RSP Architects"},
    d:{zh:"ION乌节于2009年开业，位于乌节地铁站上方，是乌节路最醒目的购物中心之一。流线型的玻璃与金属外立面入夜后变成巨大的媒体屏幕；后方是高218米的住宅塔楼，顶部设有观景台ION Sky。",
       en:"Opened in 2009 above Orchard MRT station, ION Orchard is one of the most eye-catching malls on Orchard Road. Its curving glass-and-metal front becomes a huge media screen at night. Behind it rises a 218-metre apartment tower with the ION Sky viewing gallery near the top."}},
  ngeeann: {k:{zh:"购物中心", en:"Shopping centre"}, y:"1993",
    d:{zh:"义安城于1993年开业，由潮州人社团义安公司开发。两座深色花岗岩外墙的塔楼坐落在宽阔的广场后方，造型稳重如城堡。商场内有高岛屋百货和大型纪伊国屋书店，是乌节路最大的购物中心之一。",
       en:"Ngee Ann City opened in 1993, developed by the Ngee Ann Kongsi, a Teochew community foundation. Its twin towers, clad in dark granite and set behind a wide plaza, have a solid, fortress-like look. Inside are the Takashimaya department store and a large Kinokuniya bookshop, making it one of Orchard Road's biggest malls."}},
  dukenus: {k:{zh:"医学院", en:"Medical school"},
    d:{zh:"杜克-国大医学院由新加坡国立大学与美国杜克大学于2005年合作创办，采用美式“研究生入学”的医学教育模式，学生须先取得学士学位。学院大楼位于欧南园的新加坡中央医院园区内，与医院紧密合作开展临床研究。",
       en:"Duke-NUS Medical School was founded in 2005 as a partnership between the National University of Singapore and Duke University in the United States. It follows the American graduate-entry model, so students join after earning a first degree. Its building stands on the Singapore General Hospital campus at Outram, working closely with the hospital on clinical research."}},
  nusbt: {k:{zh:"大学校园 · 国家古迹", en:"University campus, National Monument"}, y:"1928", a:{zh:"西里尔·法里与格雷厄姆·道巴恩", en:"Cyril Farey and Graham Dawbarn"},
    d:{zh:"武吉知马校区原为莱佛士学院，为纪念莱佛士登陆百年而筹建，1928年建成并迎来首批学生。1949年它与爱德华七世医学院合并为马来亚大学，是今日国大的源头之一。校园以上下两个四方庭院为中心，长期由国大法学院使用，现为国家古迹。",
       en:"This campus was built as Raffles College, planned to mark a century since Raffles' arrival, and took its first students in 1928. In 1949 it merged with the King Edward VII College of Medicine to form the University of Malaya, one of the roots of today's NUS. Set around two quadrangles, it has long been home to the NUS Faculty of Law and is a National Monument."}},
  nusbt_oth: {p:"nusbt"},
  nusbt_lib: {p:"nusbt"},
  nusbt_lks: {p:"nusbt"},
  nusbt_lt: {p:"nusbt"},

  // ---------------- Civic District (wave 2) ----------------
  capitol: {k:{zh:"历史建筑 · 剧院", en:"Historic building, theatre"}, y:"1930", a:{zh:"Keys & Dowdeswell 建筑事务所", en:"Keys & Dowdeswell"},
    d:{zh:"首都戏院于1930年开幕，是当年新加坡最豪华的电影院之一，与相邻的首都大厦共同构成史丹福路与北桥路交界的转角地标。经过整体修复后，这组建筑与史丹福楼一起以“首都新加坡”的名义于2015年重新开放，内有剧院、酒店和商店。",
       en:"Capitol Theatre opened in 1930 as one of Singapore's grandest cinemas, and with the neighbouring Capitol Building it formed a landmark corner at Stamford Road and North Bridge Road. After restoration the buildings reopened in 2015, together with Stamford House, as Capitol Singapore, with a theatre, a hotel and shops."}},
  rafflescity: {k:{zh:"综合体", en:"Mixed-use complex"}, y:"1986", h:226, fl:73, a:{zh:"贝聿铭", en:"I. M. Pei"},
    d:{zh:"莱佛士城于1986年落成，由贝聿铭设计，建在莱佛士书院的旧址上，包括商场、办公楼、会议中心和酒店。其中高226米、73层的史丹福瑞士酒店，开业时是世界最高的酒店。",
       en:"Raffles City, designed by I. M. Pei and completed in 1986, stands on the former grounds of Raffles Institution and combines a mall, offices, a convention centre and hotels. Its 73-storey, 226-metre Swissôtel The Stamford was the tallest hotel in the world when it opened."}},
  artshouse: {k:{zh:"历史建筑 · 艺术中心", en:"Historic building, arts centre"}, y:"1827", a:{zh:"乔治·科尔曼", en:"G. D. Coleman"},
    d:{zh:"旧国会大厦建于1827年，由建筑师乔治·科尔曼为苏格兰商人麦斯威尔设计，是新加坡现存最古老的政府建筑。它曾作法院，1965至1999年是新加坡国会所在地；门前的铜象是暹罗国王朱拉隆功1871年来访后赠送的。如今这里是艺术之家。",
       en:"Built in 1827 by architect G. D. Coleman as a house for Scottish merchant John Maxwell, this is Singapore's oldest surviving government building. It served as a courthouse and was home to Parliament from 1965 to 1999. The bronze elephant in front was a gift from King Chulalongkorn of Siam after his visit in 1871. Today it is The Arts House."}},
  parliament: {k:{zh:"国会大厦", en:"Parliament building"}, y:"1999",
    d:{zh:"新国会大厦于1999年启用，接替隔壁的旧国会大厦。建筑采用简洁的现代古典风格，与周边殖民地时期的建筑相协调。公众可以到旁听席观看国会会议，也可预约参观，了解新加坡的立法过程。",
       en:"The present Parliament House opened in 1999, taking over from the old building next door. Its simple, modern classical style was chosen to sit well with the colonial-era buildings around it. Members of the public can watch sittings from the gallery or book a visit to learn how laws are made in Singapore."}},
  cavenagh: {k:{zh:"桥梁", en:"Bridge"}, y:"1869",
    d:{zh:"加文纳桥建于1869年，以海峡殖民地总督加文纳命名，是新加坡河上现存最古老的桥梁之一，铁构件在苏格兰格拉斯哥制造后运来组装。如今它只供行人通行，桥头仍保留着一块旧告示牌，禁止牛马等牲口过桥。",
       en:"Built in 1869 and named after Governor William Cavenagh, this is one of the oldest bridges across the Singapore River; its ironwork was made in Glasgow and put together here. Today it is for pedestrians only, and an old sign at one end still forbids cattle and horses from crossing."}},
  anderson: {k:{zh:"桥梁", en:"Bridge"}, y:"1910",
    d:{zh:"安德逊桥于1910年启用，以时任海峡殖民地总督约翰·安德逊命名，用来分担加文纳桥日益拥挤的交通。三道钢拱横跨河口，至今仍是车行桥；每年新加坡F1夜间赛时，赛车会从桥上飞驰而过。",
       en:"Anderson Bridge opened in 1910, named after Governor John Anderson, to take traffic off the crowded Cavenagh Bridge. Its three steel arches still carry road traffic across the river mouth, and racing cars speed over it during the Singapore Grand Prix night race."}},
  asiasquare: {k:{zh:"摩天大楼", en:"Skyscrapers"}, y:"2011–2013", h:229, a:{zh:"丹顿·科克·马歇尔", en:"Denton Corker Marshall"},
    d:{zh:"亚洲广场由两座玻璃幕墙办公塔楼组成：第一座于2011年落成，高约229米；第二座于2013年落成，内设酒店。它位于老商业区与滨海湾之间，以节能环保的设计著称。",
       en:"Asia Square consists of two glass office towers: Tower 1, about 229 metres tall, was completed in 2011, and Tower 2, which includes a hotel, followed in 2013. Standing between the old business district and Marina Bay, the towers are known for their energy-saving green design."}},
  ocbc: {k:{zh:"摩天大楼", en:"Skyscraper"}, y:"1976", h:198, fl:52, a:{zh:"贝聿铭", en:"I. M. Pei"},
    d:{zh:"华侨银行大厦于1976年落成，由贝聿铭设计，高198米，建成时是东南亚最高的建筑。平整的立面夹在两侧半圆形的混凝土核心筒之间，整体像一台老式计算器，因此被昵称为“计算器大厦”。",
       en:"Completed in 1976 and designed by I. M. Pei, OCBC Centre stands 198 metres tall and was the tallest building in Southeast Asia when it opened. Its flat facade between two rounded concrete cores makes it look like an old pocket calculator, which is exactly what locals call it."}},
  thesail: {k:{zh:"住宅大楼", en:"Residential towers"}, y:"2008", h:245, fl:70, a:{zh:"NBBJ（彼得·普兰）", en:"NBBJ (Peter Pran)"},
    d:{zh:"滨海湾帆船大厦由两座住宅塔楼组成，2008年落成，较高的一座70层、约245米，曾是新加坡最高的住宅楼。玻璃立面上的弧线与斜线像被海风鼓满的船帆，与旁边的海湾相互呼应。",
       en:"The Sail @ Marina Bay is a pair of residential towers finished in 2008. The taller one has 70 storeys and rises about 245 metres, once the tallest homes in Singapore. The curves and slanted lines of the glass facades suggest sails filled with wind, echoing the bay nearby."}},
  cliffordpier: {k:{zh:"历史码头", en:"Historic pier"}, y:"1933",
    d:{zh:"红灯码头正式名称为克利福德码头，1933年启用，以总督克利福德命名，装饰艺术风格的混凝土拱形屋架十分优雅。旧时码头末端挂着一盏红灯为船只引航，华人因而叫它“红灯码头”。码头于2006年停用，如今与旁边的旧海关大楼一起成为富丽敦海湾酒店一带的餐饮场所。",
       en:"Clifford Pier opened in 1933, named after Governor Hugh Clifford, with elegant Art Deco arched concrete roof trusses. A red lantern once hung at its end to guide boats, so Chinese residents called it the 'Red Lantern Pier'. It closed as a landing point in 2006 and, with the old Customs House next door, now hosts restaurants by The Fullerton Bay Hotel."}},
  ktmstation: {k:{zh:"历史火车站", en:"Historic railway station"}, y:"1932",
    d:{zh:"丹戎巴葛火车站于1932年启用，是马来亚铁路的南端终点站，2011年最后一班列车开出后停止运营，同年被列为国家古迹。装饰艺术风格的立面上有意大利雕塑家诺利创作的四座人像，分别象征农业、商业、交通和工业。",
       en:"Tanjong Pagar Railway Station opened in 1932 as the southern end of the Malayan Railway. Trains stopped after the last departure in 2011, and it became a National Monument the same year. Four figures by Italian sculptor Rodolfo Nolli on its Art Deco front stand for Agriculture, Commerce, Transport and Industry."}},
  firestation: {k:{zh:"消防局", en:"Fire station"}, y:"1909",
    d:{zh:"中央消防局建于1909年，是新加坡现存最古老的消防局，至今仍在运作。红白相间的砖墙条纹被戏称为“血与绷带”风格；高高的瞭望塔当年用来观察全城火情。局内设有民防文物馆，介绍新加坡消防的历史。",
       en:"Built in 1909, Central Fire Station is Singapore's oldest fire station and is still in service. Its red-and-white brick stripes are nicknamed the 'blood and bandage' style, and the tall tower was once used to spot fires across the town. The Civil Defence Heritage Gallery inside tells the story of firefighting in Singapore."}},
  goodshepherd: {k:{zh:"天主教座堂", en:"Catholic cathedral"}, y:"1847",
    d:{zh:"善牧主教座堂于1847年落成，是新加坡最古老的天主教堂，平面呈拉丁十字形，尖塔高耸。它是新加坡天主教总主教的座堂，1973年被列为国家古迹，并在2010年代完成了全面修复。",
       en:"Completed in 1847, the Cathedral of the Good Shepherd is Singapore's oldest Roman Catholic church, built on a Latin cross plan with a tall spire. It is the seat of the Archbishop of Singapore, became a National Monument in 1973 and was carefully restored in the 2010s."}},
  armenian: {k:{zh:"教堂", en:"Church"}, y:"1835", a:{zh:"乔治·科尔曼", en:"G. D. Coleman"},
    d:{zh:"亚美尼亚教堂由乔治·科尔曼设计，1835年落成，是新加坡现存最古老的基督教堂，由人数不多却很有影响力的亚美尼亚社群兴建。教堂庭院里立着艾妮丝·卓锦的墓碑，她培育的“卓锦万代兰”后来成为新加坡国花。",
       en:"Designed by G. D. Coleman and completed in 1835, the Armenian Church is the oldest surviving Christian church in Singapore, built by a small but influential Armenian community. Its garden holds the gravestone of Agnes Joaquim, who bred the orchid Vanda Miss Joaquim, now Singapore's national flower."}},
  peranakan: {k:{zh:"博物馆", en:"Museum"}, y:"1912",
    d:{zh:"土生华人博物馆设在1912年建成的旧道南学校里，这是一座折衷主义风格的白色建筑。博物馆介绍新加坡及东南亚土生华人（峇峇娘惹）的文化，展出精美的珠绣、瓷器、家具和婚礼服饰，翻新后于2023年重新开放。",
       en:"The Peranakan Museum occupies the old Tao Nan School, a white eclectic-style building completed in 1912. It presents the culture of the Peranakan Chinese of Singapore and Southeast Asia through beadwork, porcelain, furniture and wedding costumes, and reopened in 2023 after a major refresh."}},
  sam: {k:{zh:"美术馆", en:"Art museum"},
    d:{zh:"新加坡美术馆的老馆位于前圣约瑟书院的校舍内，这座带弧形侧翼和中央圆顶的19世纪建筑曾是一所天主教男校。美术馆于1996年在此开馆，专注当代艺术；近年老馆闭馆翻新，美术馆转到丹戎巴葛货运码头等地点继续办展。",
       en:"Singapore Art Museum's home building was once St Joseph's Institution, a Catholic boys' school; the 19th-century building has curved wings and a central dome. The museum opened here in 1996 with a focus on contemporary art. In recent years the building has been closed for redevelopment, and the museum has staged shows at Tanjong Pagar Distripark and elsewhere."}},
  mhfatimah: {k:{zh:"清真寺", en:"Mosque"}, y:"1846",
    d:{zh:"哈贾法蒂玛回教堂建于1846年，以出身马六甲的女商人哈贾·法蒂玛命名，她出资在自家旧宅的原址上建了这座清真寺。建筑融合欧洲与马来风格，尖塔明显向一侧倾斜，因此有“新加坡比萨斜塔”之称。",
       en:"Built in 1846, this mosque is named after Hajjah Fatimah, a Malacca-born businesswoman who paid for it on the site of her former home. It blends European and Malay styles, and its minaret leans noticeably to one side, earning it the nickname 'the leaning tower of Singapore'."}},
  malayheritage: {k:{zh:"博物馆 · 历史宫殿", en:"Museum, former palace"},
    d:{zh:"马来传统文化馆设在甘榜格南王宫内，这座宫殿建于1840年代，是苏丹侯赛因之子苏丹阿里的居所。修复后于2005年作为文化馆开放，通过文物和多媒体展示马来社群在新加坡的历史、语言与艺术。",
       en:"The Malay Heritage Centre is housed in the Istana Kampong Gelam, a palace built in the 1840s for Sultan Ali, son of Sultan Hussein. Restored and opened as a museum in 2005, it uses objects and multimedia to tell the history, language and arts of the Malay community in Singapore."}},
  tangplaza: {k:{zh:"酒店 · 百货", en:"Hotel and department store"}, y:"1982",
    d:{zh:"董厦于1982年落成，由TANGS百货创办人董俊竞的家族开发。酒店塔楼顶部覆盖着绿色琉璃瓦的中式屋顶，在乌节路与史各士路交界处格外醒目；底层的TANGS百货则由他早年开设的小商铺发展而来。",
       en:"Tang Plaza was completed in 1982 by the family of C. K. Tang, founder of the TANGS department store. The hotel tower is topped with green-tiled Chinese-style roofs that stand out at the corner of Orchard and Scotts Roads, and the TANGS store below grew out of the small shop he started decades earlier."}},
  goodwood: {k:{zh:"历史酒店", en:"Historic hotel"}, y:"1900", a:{zh:"R. A. J. 比德韦尔（斯旺与麦克拉伦）", en:"R. A. J. Bidwell (Swan & Maclaren)"},
    d:{zh:"良木园酒店的塔楼建于1900年，原是德国侨民的“条顿俱乐部”，第一次世界大战后被收归，1929年改作酒店。带尖塔的白色建筑融合了德国与维多利亚风格，1989年被列为国家古迹。",
       en:"The tower block of the Goodwood Park Hotel was built in 1900 as the Teutonia Club for Singapore's German community. It was taken over after the First World War and became a hotel in 1929. The white building with its corner tower mixes German and Victorian styles and became a National Monument in 1989."}},
  istana: {k:{zh:"总统府", en:"Presidential palace"}, y:"1867–1869", a:{zh:"约翰·麦克奈尔", en:"J. F. A. McNair"},
    d:{zh:"总统府建于1867至1869年，原为英国殖民地总督府，由约翰·麦克奈尔设计，印度囚犯劳工参与建造。如今这里是新加坡总统的官邸和办公地，也用来接待外国元首。园区平时不开放，但每年会在几个节日举办开放日。",
       en:"The Istana was built between 1867 and 1869 as Government House for the British governor, designed by J. F. A. McNair and built partly by Indian convict labour. It is now the official residence and office of the President of Singapore and is used to receive state guests. The grounds open to the public on a few holidays each year."}},
  srinivasa: {k:{zh:"兴都庙", en:"Hindu temple"}, y:"1855",
    d:{zh:"斯里尼维沙柏鲁马兴都庙始建于1855年，供奉毗湿奴的化身柏鲁马，是小印度最重要的寺庙之一。入口上方五层高的门塔于1966年建成，布满神像雕塑；每年大宝森节的游行队伍就从这里出发。",
       en:"Founded in 1855, Sri Srinivasa Perumal Temple is dedicated to Perumal, a form of Vishnu, and is one of the most important temples in Little India. Its five-tier entrance tower, added in 1966, is covered with sculptures of deities, and the yearly Thaipusam procession starts from here."}},
  kmspks: {k:{zh:"佛寺", en:"Buddhist monastery"}, y:"1921",
    d:{zh:"光明山普觉禅寺由转道法师于1921年创立，是新加坡规模最大的佛教寺院。寺内的殿堂、宝塔和纪念建筑沿着山坡层层展开；寺院也兴办佛教教育与慈善事业。",
       en:"Founded in 1921 by the Venerable Zhuan Dao, Kong Meng San Phor Kark See Monastery on Bright Hill is the largest Buddhist monastery in Singapore. Its halls, pagoda and memorial buildings spread across the slope, and the monastery also runs Buddhist education and charity work."}},
  shuanglin: {k:{zh:"佛寺", en:"Buddhist monastery"}, y:"1902–1909",
    d:{zh:"莲山双林寺由富商刘金榜发起，于1902至1909年间建成，是新加坡最古老的佛教寺院之一。殿宇依照中国南方传统沿中轴线依次排开，木雕和石雕十分精细；1980年被列为国家古迹，旁边的七层宝塔是后来增建的。",
       en:"Lian Shan Shuang Lin Monastery was started by the merchant Low Kim Pong and built between 1902 and 1909, making it one of Singapore's oldest Buddhist monasteries. Its halls line up along a central axis in southern Chinese style, with fine wood and stone carving. It became a National Monument in 1980; the seven-storey pagoda beside it was added later."}},

  // ---------------- Southern Ridges / outer areas ----------------
  hendersonwaves: {k:{zh:"人行桥", en:"Footbridge"}, y:"2008", a:{zh:"IJP 公司与 RSP 建筑事务所", en:"IJP Corporation with RSP Architects"},
    d:{zh:"亨德森波浪桥于2008年启用，全长274米，距下方的亨德森路约36米，是新加坡最高的人行桥。七道起伏的木质“肋条”像海浪般卷起，形成可供休息的凹座。它连接花柏山与直落布兰雅山，是南部山脊步道的一段。",
       en:"Opened in 2008, Henderson Waves is a 274-metre footbridge about 36 metres above Henderson Road, the highest pedestrian bridge in Singapore. Seven wavy timber 'ribs' curl over the deck, forming sheltered alcoves to rest in. It links Mount Faber and Telok Blangah Hill as part of the Southern Ridges trail."}},
  reflections: {k:{zh:"住宅", en:"Residential"}, y:"2011", fl:41, a:{zh:"丹尼尔·里伯斯金", en:"Daniel Libeskind"},
    d:{zh:"丽珀苑由建筑师丹尼尔·里伯斯金设计，2011年落成，由六座高低错落的弧形玻璃塔楼和一组低层别墅组成。塔楼之间以空中花园相连，曲面玻璃映出吉宝湾的海水与天空，正呼应它的英文名“倒影”。",
       en:"Designed by Daniel Libeskind and completed in 2011, Reflections at Keppel Bay has six curved glass towers of different heights and a group of low-rise villa blocks. Sky gardens bridge between the towers, and the curved glass reflects the water and sky of Keppel Bay, just as the name suggests."}},
  vivocity: {k:{zh:"购物中心", en:"Shopping mall"}, y:"2006", a:{zh:"伊东丰雄", en:"Toyo Ito"},
    d:{zh:"怡丰城于2006年开业，由日本建筑师伊东丰雄设计，是新加坡最大的购物中心之一。波浪形的屋顶和外墙呼应旁边的港口，楼顶有带浅水池的露天花园。这里也是前往圣淘沙的门户，可在此搭乘圣淘沙捷运。",
       en:"VivoCity opened in 2006 and was designed by Japanese architect Toyo Ito; it is one of Singapore's largest malls. Its wavy roof and facade echo the harbour next door, and the rooftop has an open-air park with a shallow pool. It is also the gateway to Sentosa, with the Sentosa Express monorail leaving from here."}},
  chinesegarden: {k:{zh:"园林", en:"Garden"}, y:"1975",
    d:{zh:"裕华园于1975年开放，仿照中国北方皇家园林的风格建造，园中有拱桥、亭台和一座七层宝塔。它坐落在裕廊湖中的小岛上，如今是裕廊湖花园的一部分，并以桥与相邻的日本庭园（星和园）相连。",
       en:"The Chinese Garden opened in 1975, built in the style of the imperial gardens of northern China, with arched bridges, pavilions and a seven-storey pagoda. It sits on an island in Jurong Lake, is now part of Jurong Lake Gardens, and is linked by a bridge to the Japanese Garden next door."}},
  kranji: {k:{zh:"战争纪念碑与墓园", en:"War memorial and cemetery"}, y:"1957", a:{zh:"科林·圣克莱尔·奥克斯", en:"Colin St Clair Oakes"},
    d:{zh:"克兰芝战争纪念碑于1957年揭幕，纪念二战中为保卫新加坡和马来亚而牺牲的盟军将士。山坡上排列着四千多座墓碑，纪念墙上刻着两万四千多名下落不明者的名字。立柱代表陆军，机翼般的屋顶代表空军，顶端形似潜望镜，代表海军。",
       en:"Unveiled in 1957, the Kranji War Memorial honours Allied servicemen who died defending Singapore and Malaya in the Second World War. More than 4,000 graves line the slope, and the walls carry over 24,000 names of those with no known grave. Its columns stand for the army, the wing-shaped roof for the air force and the periscope-like top for the navy."}},
  tampineshub: {k:{zh:"社区中心", en:"Community hub"}, y:"2017", a:{zh:"DP建筑师事务所", en:"DP Architects"},
    d:{zh:"我们的淡滨尼中心于2017年启用，是新加坡最大的综合社区与生活中心，把图书馆、小贩中心、体育馆、游泳池、政府服务和社区活动空间集中在一处。中央的大草坪可以踢足球、办活动；项目在规划阶段广泛听取了居民的意见。",
       en:"Opened in 2017, Our Tampines Hub is Singapore's largest integrated community and lifestyle centre, bringing a library, hawker centre, sports halls, swimming pools, public services and community spaces under one roof. Its central field hosts football and events, and residents were widely consulted while it was being planned."}},

  // ---------------- Esplanade Park / Padang (lm26 sgcivic) ----------------
  sgwarmem: {k:{zh:"纪念碑", en:"Memorial"}, y:"1967", a:{zh:"Leong Swee Lim（斯旺与麦克拉伦）", en:"Leong Swee Lim (Swan & Maclaren)"},
    d:{zh:"日本占领时期死难人民纪念碑于1967年2月15日揭幕，正值新加坡沦陷25周年。四根白色混凝土立柱代表华族、马来族、印度族和其他族群共同承受的苦难，被人们称为“筷子”。碑下安葬着战后寻获的无名遇难者遗骸，每年2月15日都在这里举行追思仪式。",
       en:"This memorial was unveiled on 15 February 1967, exactly 25 years after the fall of Singapore. Its four white concrete columns stand for the shared suffering of the Chinese, Malay, Indian and other communities, and are often called 'the chopsticks'. Remains of unidentified civilian victims lie beneath it, and a remembrance ceremony is held here every 15 February."}},
  sgcenotaph: {k:{zh:"纪念碑", en:"War memorial"}, y:"1922", a:{zh:"丹尼斯·桑特里（斯旺与麦克拉伦）", en:"Denis Santry (Swan & Maclaren)"},
    d:{zh:"和平纪念碑纪念在第一次世界大战中阵亡的新加坡人，1922年由英国威尔士亲王爱德华揭幕；1951年又在另一面加上纪念第二次世界大战死难者的铭文。附近还有1954年建成的林谋盛纪念塔，纪念抗日英雄林谋盛。",
       en:"The Cenotaph honours those from Singapore who died in the First World War and was unveiled in 1922 by Edward, Prince of Wales. Its other side was dedicated in 1951 to the dead of the Second World War. Nearby stands the Lim Bo Seng Memorial of 1954, for the wartime resistance hero."}},
  sgtankimseng: {k:{zh:"喷泉", en:"Fountain"}, y:"1882",
    d:{zh:"陈金声喷泉建于1882年，纪念富商陈金声捐款协助新加坡兴建第一个正式的供水系统。这座维多利亚风格的铸铁喷泉在英国制造，原本立在富丽敦广场，1925年迁到滨海公园，如今是国家古迹。",
       en:"Built in 1882, this fountain honours the merchant Tan Kim Seng, who gave money towards Singapore's first proper water supply. The Victorian cast-iron fountain was made in Britain and first stood at Fullerton Square before moving to Esplanade Park in 1925. It is now a National Monument."}},
  sgcricket: {k:{zh:"俱乐部", en:"Sports club"}, y:"1884",
    d:{zh:"新加坡板球俱乐部成立于1852年，是新加坡最古老的体育俱乐部之一。会所于1884年建成，后来多次扩建，坐落在巴东草场西南端；面前的草场上举行过无数板球、橄榄球比赛和国家庆典。",
       en:"Founded in 1852, the Singapore Cricket Club is one of the oldest sports clubs in Singapore. Its clubhouse, first built in 1884 and later extended, stands at the south-west end of the Padang, where cricket and rugby matches and many national celebrations have taken place."}},
  sgsrc: {k:{zh:"俱乐部", en:"Sports club"},
    d:{zh:"新加坡康乐俱乐部由欧亚裔社群于1883年创办，坐落在巴东草场东北端，与另一头的板球俱乐部遥遥相对。殖民地时代板球俱乐部只接纳欧洲人，康乐俱乐部便成了欧亚裔运动与社交的据点。今天的会所是后来重建的现代建筑。",
       en:"The Singapore Recreation Club was founded in 1883 by the Eurasian community and stands at the north-east end of the Padang, facing the Cricket Club at the other end. In colonial times, when the Cricket Club admitted only Europeans, it became the sporting and social home of Eurasians. Today's clubhouse is a modern rebuild."}},
  sgconcourse: {k:{zh:"摩天大楼", en:"Skyscraper"}, h:175, a:{zh:"保罗·鲁道夫", en:"Paul Rudolph"},
    d:{zh:"鸿福中心由美国建筑师保罗·鲁道夫设计，于1990年代中期落成。八角形塔楼的每层都向外伸出尖角形的遮阳板，层层叠叠像一朵向上展开的花，让它在美芝路的高楼中很容易辨认。",
       en:"The Concourse was designed by American architect Paul Rudolph and completed in the mid-1990s. Its octagonal tower is wrapped in pointed sunshades that fan out floor after floor like the petals of a flower, making it easy to spot among the towers on Beach Road."}},
  sgstjoseph: {k:{zh:"教堂", en:"Church"}, y:"1912",
    d:{zh:"圣约瑟教堂于1912年落成，由葡萄牙传教团兴建，长期归澳门教区管辖，直到1999年才转归新加坡总教区。这座哥特式教堂以八角形塔楼和色彩缤纷的彩色玻璃窗著称，2005年被列为国家古迹。",
       en:"St Joseph's Church was completed in 1912 by the Portuguese Mission and remained under the Diocese of Macau until 1999, when it came under the Archdiocese of Singapore. The Gothic church is known for its octagonal towers and colourful stained-glass windows, and became a National Monument in 2005."}},

  // ---------------- Singapore River (lm26 sgriver) ----------------
  sgclarkequay: {k:{zh:"河畔历史街区", en:"Riverside heritage quay"},
    d:{zh:"克拉码头以第二任海峡殖民地总督安德鲁·克拉克命名，19世纪时沿河排满货栈，驳船在这里装卸货物。1990年代仓库被修复为餐饮娱乐区，2006年改造时加上了色彩缤纷的伞形顶棚为街道遮阳挡雨，如今是新加坡最热闹的夜生活地带之一。",
       en:"Clarke Quay is named after Sir Andrew Clarke, the second Governor of the Straits Settlements. In the 19th century it was lined with warehouses served by small boats on the river. The warehouses were restored for restaurants and entertainment in the 1990s, and in 2006 colourful umbrella-like canopies were added to shade the streets. It is now one of Singapore's liveliest nightspots."}},
  sgboatquay: {k:{zh:"河畔历史街区", en:"Riverside heritage quay"},
    d:{zh:"驳船码头位于新加坡河南岸，19世纪中叶是港口最繁忙的地段，经手了大量航运生意。华人把弯曲的河岸看作“鲤鱼肚”，象征财富。如今修复后的两三层店屋里开满了餐馆和酒吧，对岸就是市政区。",
       en:"Boat Quay runs along the south bank of the Singapore River and was the busiest part of the port in the mid-19th century, handling much of the colony's shipping trade. Chinese merchants saw the curved bank as the belly of a carp, a sign of wealth. Today its restored shophouses are full of restaurants and bars facing the civic district across the river."}},
  sgelgin: {k:{zh:"桥梁", en:"Bridge"}, y:"1929",
    d:{zh:"艾尔金桥于1929年建成，以曾任印度总督的额尔金勋爵命名，连接北桥路和南桥路。新加坡河上的第一座桥——1820年代的木桥——就建在这个位置。桥上的铸铁灯柱和徽章出自意大利雕塑家诺利之手。",
       en:"Elgin Bridge was completed in 1929 and named after Lord Elgin, a former Governor-General of India; it links North and South Bridge Roads. The very first bridge across the Singapore River, a wooden one from the 1820s, stood on this spot. The cast-iron lamps and medallions on the bridge are by Italian sculptor Rodolfo Nolli."}},
  sgcoleman: {k:{zh:"桥梁", en:"Bridge"}, y:"1990",
    d:{zh:"哥里门桥以早期殖民地建筑师乔治·科尔曼命名，他在1840年设计了这里的第一座桥。桥梁几经重建，现今的桥于1990年落成，保留了1886年旧桥的装饰灯柱和拱形栏杆，连接禧街与新桥路。",
       en:"Coleman Bridge is named after George Coleman, the early colonial architect who designed the first bridge here in 1840. It has been rebuilt several times; the present bridge dates from 1990 and keeps the decorative lamps and arched railings of the 1886 version. It links Hill Street with New Bridge Road."}},
  sgalkaff: {k:{zh:"人行桥", en:"Footbridge"}, y:"1997",
    d:{zh:"阿卡夫桥建于1997年，以阿拉伯裔商人阿卡夫家族命名，造型模仿昔日河上往来的驳船。2004年，菲律宾艺术家帕西塔·阿巴德用五十多种颜色、约两千个圆圈把整座钢桥漆成一件巨型艺术品，成为罗伯逊码头最活泼的风景。",
       en:"Alkaff Bridge was built in 1997, named after the Arab merchant Alkaff family, and shaped like the bumboats that once worked the river. In 2004 Filipino artist Pacita Abad painted the steel bridge with more than 50 colours and some 2,000 circles, turning it into a giant artwork at Robertson Quay."}},
  sgjamae: {k:{zh:"清真寺", en:"Mosque"}, y:"1830–1835",
    d:{zh:"詹美回教堂由来自南印度科罗曼德海岸的朱利亚穆斯林于1826年前后创建，现今的建筑在1830至1835年间建成，是新加坡最古老的清真寺之一。正门两侧的塔楼一层层向上收小，融合了南印度与新古典主义等多种风格。",
       en:"Masjid Jamae was founded around 1826 by Chulia Muslims from the Coromandel Coast of southern India, and the present building went up between 1830 and 1835, making it one of Singapore's oldest mosques. The twin towers beside the gate, with their stacked, shrinking tiers, mix South Indian and neoclassical styles."}},
  sgmajestic: {k:{zh:"历史戏院", en:"Historic theatre"}, y:"1928",
    d:{zh:"大华戏院于1928年由富商余东旋兴建，最初是上演粤剧的戏院，后来改为电影院。正立面带有中式瓦檐、彩绘瓷砖和镀金装饰，是牛车水少见的中式装饰建筑，见证了本地广府社群的娱乐生活。",
       en:"The Majestic was built in 1928 by tycoon Eu Tong Sen as a theatre for Cantonese opera and later became a cinema. Its facade, with Chinese tiled eaves, painted tiles and gilded details, is a rare piece of Chinese-style decoration in Chinatown and recalls the entertainment life of the local Cantonese community."}},

  // ---------------- CBD (lm26 sgcbd) ----------------
  sgcapitagreen: {k:{zh:"摩天大楼", en:"Skyscraper"}, y:"2014", fl:40, a:{zh:"伊东丰雄", en:"Toyo Ito"},
    d:{zh:"凯德·绿于2014年落成，由日本建筑师伊东丰雄设计。外墙大面积覆盖着绿色植物，楼顶“空中森林”上方有一个红色的“风斗”，把高处较凉爽的空气引入楼内，帮助减少空调能耗。",
       en:"CapitaGreen, completed in 2014, was designed by Japanese architect Toyo Ito. Much of its facade is covered with plants, and above the sky forest at the top a red 'wind scoop' catches cooler air high up and draws it down into the building to cut the need for air conditioning."}},
  sgoasia: {k:{zh:"酒店", en:"Hotel"}, y:"2016", fl:27, a:{zh:"WOHA建筑事务所", en:"WOHA"},
    d:{zh:"市中豪亚酒店于2016年落成，由新加坡WOHA建筑事务所设计。红色铝网外墙上攀满了二十多种爬藤植物，楼内在多个高度开出通透的空中花园，被视为热带“垂直绿化”的代表作，在周围的玻璃幕墙中格外显眼。",
       en:"Oasia Hotel Downtown, completed in 2016, was designed by Singapore firm WOHA. Its red aluminium mesh skin is covered in more than 20 kinds of climbing plants, and open sky gardens are cut into the tower at several levels. It is seen as a model of tropical vertical greenery and stands out among the glass towers around it."}},
  sgofc: {k:{zh:"摩天大楼", en:"Skyscraper"}, y:"2011", h:245, fl:43,
    d:{zh:"海洋金融中心高245米、共43层，2011年在哥烈码头落成，取代了原址上的旧海洋大厦。大楼在设计上注重节能，低层外墙还有一大片垂直绿墙，柔化了建筑的外观。",
       en:"Ocean Financial Centre, 245 metres tall with 43 storeys, was completed on Collyer Quay in 2011, replacing the older Ocean Building on the site. It was designed with a strong focus on saving energy, and a large green wall softens its lower floors."}},
  sgconfhall: {k:{zh:"历史建筑 · 音乐厅", en:"Historic building, concert hall"}, y:"1965", a:{zh:"马来亚建筑师联合事务所（林崇杰）", en:"Malayan Architects Co-Partnership (Lim Chong Keat)"},
    d:{zh:"新加坡大会堂于1965年落成，由林崇杰领衔的马来亚建筑师联合事务所设计，是新加坡早期现代主义建筑的代表。它原本兼作会议厅和职工总会会所，举办过许多重要会议；2001年起成为新加坡华乐团的驻团场地，2010年被列为国家古迹。",
       en:"Completed in 1965, the Singapore Conference Hall was designed by the Malayan Architects Co-Partnership led by Lim Chong Keat and is a fine early example of modern architecture in Singapore. It first served as a conference hall and trade union house, hosting many major meetings. Since 2001 it has been home to the Singapore Chinese Orchestra, and it became a National Monument in 2010."}},
  sgtelokayer: {k:{zh:"教堂", en:"Church"}, y:"1925",
    d:{zh:"直落亚逸礼拜堂的会众创立于1889年，是新加坡最早的华人卫理公会教会之一，现今的礼拜堂于1925年落成。建筑在西式结构上融入中式元素，最特别的是屋顶上的那座中式凉亭；1989年被列为国家古迹。",
       en:"Telok Ayer Chinese Methodist Church began in 1889 as one of the first Chinese Methodist congregations in Singapore, and its present building was finished in 1925. It mixes a Western structure with Chinese elements, most strikingly the Chinese pavilion on its roof. It became a National Monument in 1989."}},
  sglayan: {k:{zh:"兴都庙", en:"Hindu temple"}, y:"1925",
    d:{zh:"斯里拉央西迪维纳亚加兴都庙由来自南印度的切蒂亚尔社群于1925年创建，供奉象头神维纳亚加（即甘尼许）。寺庙位于牛车水的恭锡路，入口上方的门塔布满彩绘神像，在一排排店屋之间格外醒目。",
       en:"Sri Layan Sithi Vinayagar Temple was founded in 1925 by the Chettiar community from southern India and is dedicated to Vinayagar, the elephant-headed god also known as Ganesha. It stands on Keong Saik Road in Chinatown, where its entrance tower full of painted deities stands out among the shophouses."}},
  sgnagore: {k:{zh:"伊斯兰圣祠", en:"Muslim shrine"}, y:"1828–1830",
    d:{zh:"纳哥德卡圣祠建于1828至1830年间，由南印度的朱利亚穆斯林兴建，纪念来自纳哥尔的苏菲派圣人沙胡尔·哈米德。建筑融合印度伊斯兰与古典风格，正面有细致的镂空屏风和多座纤细的小尖塔，如今是印度穆斯林文化遗产中心。",
       en:"Nagore Dargah was built between 1828 and 1830 by Chulia Muslims from southern India to honour Shahul Hamid, a Sufi saint from Nagore. It blends Indian-Islamic and classical styles, with a finely pierced screen facade and slender minarets. Today it is the Nagore Dargah Indian Muslim Heritage Centre."}},

  // ---------------- Little India / Bugis (lm26 sgbugis) ----------------
  sgveeramakali: {k:{zh:"兴都庙", en:"Hindu temple"}, y:"1855",
    d:{zh:"维拉马卡里亚曼兴都庙由早期来自印度的劳工于1855年创建，供奉象征勇气与力量的迦梨女神，是小印度最古老的寺庙之一。实龙岗路旁高耸的门塔挤满彩色神像，每天都有许多信众前来祈福。",
       en:"Sri Veeramakaliamman Temple was founded in 1855 by early Indian labourers and is dedicated to the goddess Kali, a symbol of courage and strength. One of the oldest temples in Little India, it has a tall entrance tower crowded with colourful deities on Serangoon Road and draws many worshippers every day."}},
  sgabdulgafoor: {k:{zh:"清真寺", en:"Mosque"}, y:"1910",
    d:{zh:"阿都卡夫回教堂于1910年落成，取代了原址上的旧清真寺，以管理信托的谢赫·阿都卡夫命名。入口上方的“太阳”装饰有25道光芒，每一道都用阿拉伯书法写着一位《古兰经》提到的先知的名字。1979年被列为国家古迹。",
       en:"Masjid Abdul Gafoor was completed in 1910 on the site of an older mosque and named after Shaik Abdul Gafoor, who managed its trust. Above the entrance a sunburst has 25 rays, each carrying the name of one of the 25 prophets of the Quran in Arabic calligraphy. It became a National Monument in 1979."}},
  sgtantengniah: {k:{zh:"历史住宅", en:"Historic villa"}, y:"1900",
    d:{zh:"陈东龄故居建于1900年，据说是商人陈东龄为妻子所建，是小印度仅存的华人传统别墅。这座两层楼的房子漆成彩虹般的鲜艳色彩，门窗和木雕细节丰富，是这一带最受欢迎的拍照地点之一。",
       en:"The House of Tan Teng Niah was built in 1900, reportedly by the businessman for his wife, and is the last surviving Chinese villa in Little India. The two-storey house is painted in bright rainbow colours with richly detailed doors, windows and woodwork, making it one of the most photographed spots in the area."}},
  sgkwanim: {k:{zh:"华人庙宇 · 兴都庙", en:"Chinese temple and Hindu temple"},
    d:{zh:"滑铁卢街上的观音堂佛祖庙创建于1884年，香火鼎盛，许多人来此拜观音、求签。隔壁的克里斯南兴都庙供奉黑天神克里斯南。两座庙宇比邻而立，不少信众两边都会参拜，被视为新加坡宗教和谐的缩影。",
       en:"Kwan Im Thong Hood Cho Temple on Waterloo Street was founded in 1884 and is one of the busiest Chinese temples in Singapore, where many come to pray to Guan Yin and draw fortune sticks. Next door, Sri Krishnan Temple is dedicated to the Hindu god Krishna. Many devotees visit both, and the pair is often seen as a picture of religious harmony in Singapore."}},
  sglasalle: {k:{zh:"艺术学院", en:"Arts college"}, y:"2007", a:{zh:"RSP建筑事务所", en:"RSP Architects"},
    d:{zh:"拉萨尔艺术学院由约瑟·麦纳利修士于1984年创办，2007年迁入麦纳利街的新校园。几座黑色立方体建筑围合出一道“峡谷”，峡谷两侧的玻璃幕墙像碎裂的水晶，内外空间相互渗透，是武吉士一带的当代建筑地标。",
       en:"LASALLE College of the Arts was founded in 1984 by Brother Joseph McNally and moved to its McNally Street campus in 2007. Its black cube-like blocks enclose a 'canyon' lined with fractured glass walls, so the spaces inside and outside flow into each other, a contemporary landmark near Bugis."}},
  sgfortcanning: {k:{zh:"历史公园", en:"Historic park"}, y:"1859",
    d:{zh:"福康宁山古称“禁山”，14世纪时是古代淡马锡王宫的所在地，后来莱佛士也在山上建了住所。英军于1859年在此修筑炮台，如今留下古堡门等遗迹；福康宁中心原是1926年的军营。山中还有二战时英军指挥部的地下掩体。",
       en:"Fort Canning Hill was once called Bukit Larangan, the 'Forbidden Hill', where the palaces of 14th-century Temasek stood; Raffles later built his house here. The British began a fort on the hill in 1859, of which the Fort Gate survives, and Fort Canning Centre was built as army barracks in 1926. An underground British command bunker from the Second World War lies inside the hill."}},
  sgmacdonald: {k:{zh:"历史办公楼", en:"Historic office building"}, y:"1949", a:{zh:"巴马丹拿（Palmer & Turner）", en:"Palmer & Turner"},
    d:{zh:"麦唐纳大厦于1949年为汇丰银行建成，以英国驻东南亚最高专员麦唐纳命名，是新加坡最早的全空调办公楼之一。1965年印尼对抗期间，这里发生炸弹爆炸，造成三人死亡。这座红砖大楼如今受到保护。",
       en:"Completed in 1949 for the Hongkong and Shanghai Bank, MacDonald House is named after Malcolm MacDonald, Britain's Commissioner-General for Southeast Asia, and was one of the first fully air-conditioned office buildings in Singapore. In 1965, during the Indonesian Confrontation, a bomb exploded here, killing three people. The red-brick building is now protected."}},

  // ---------------- outer Singapore (lm26 sgouter) ----------------
  sgsiloso: {k:{zh:"观景步道", en:"Elevated walkway"}, y:"2015",
    d:{zh:"西乐索炮台空中步道于2015年启用，游客可乘电梯登上11层楼高的塔楼，再沿181米长的空中步道穿过树冠，抵达西乐索炮台。炮台是新加坡唯一保存完好的海防要塞，如今是介绍二战历史的博物馆。",
       en:"Opened in 2015, the Fort Siloso Skywalk lets visitors take a lift up an 11-storey tower and then walk 181 metres through the treetops to Fort Siloso. The fort is Singapore's only preserved coastal fort and is now a museum about the Second World War."}},
  sgrafflesltd: {k:{zh:"灯塔", en:"Lighthouse"}, y:"1855",
    d:{zh:"莱佛士灯塔于1855年建成，位于新加坡南部海域的沙都姆岛上，以新加坡开埠者莱佛士命名。它至今仍守护着繁忙的新加坡海峡航道，岛上平时不对公众开放。",
       en:"Raffles Lighthouse was completed in 1855 on Pulau Satumu, an island off Singapore's southern edge, and is named after Stamford Raffles. It still guards the busy shipping lanes of the Singapore Strait. The island is normally closed to the public."}},
  sgjurongtower: {k:{zh:"瞭望塔", en:"Lookout tower"}, y:"1969", h:18, a:{zh:"裕廊镇管理局", en:"Jurong Town Corporation"},
    d:{zh:"裕廊山瞭望塔于1969年建成，高约18米，没有楼梯，游客沿螺旋坡道绕行而上，可俯瞰裕廊工业区。它见证了新加坡工业化的起步；山上的“名人花园”里，许多来访的外国领袖和名人都种下了纪念树。",
       en:"Built in 1969, the 18-metre Jurong Hill Lookout Tower has no stairs: visitors walk up a spiral ramp for views over the Jurong industrial estate. It recalls the early days of Singapore's industrialisation, and in the Garden of Fame nearby many visiting leaders and celebrities have planted trees."}},
  sgkallangairport: {k:{zh:"历史机场建筑", en:"Historic airport terminal"}, y:"1937", a:{zh:"弗兰克·多林顿·沃德（公共工程局）", en:"Frank Dorrington Ward (Public Works Department)"},
    d:{zh:"旧加冷机场于1937年启用，是新加坡第一座专门建造的民用机场，当年被誉为大英帝国最好的机场之一。航站楼采用流线型的装饰艺术风格，有层层出挑的平台和大面积玻璃窗。1955年航班迁往巴耶利峇后，这里长期作为人民协会总部。",
       en:"Kallang Airport opened in 1937 as Singapore's first purpose-built civil airport and was once praised as one of the finest in the British Empire. Its streamlined Art Deco terminal has tiered, cantilevered decks and large windows. After flights moved to Paya Lebar in 1955, the building long served as the headquarters of the People's Association."}},
  sgbotanic: {k:{zh:"植物园 · 世界遗产", en:"Botanic garden, World Heritage Site"}, y:"1859",
    d:{zh:"新加坡植物园创建于1859年，2015年列入联合国教科文组织世界遗产名录，是新加坡首个世界遗产，也是首个入选的热带植物园。园内的八角形音乐台建于1930年，四周环绕着雨树；橡胶在马来亚的推广种植也是从这里的研究开始的。",
       en:"Founded in 1859, the Singapore Botanic Gardens became a UNESCO World Heritage Site in 2015, Singapore's first and the first tropical botanic garden on the list. The octagonal Bandstand, built in 1930, is ringed by rain trees, and the spread of rubber planting across Malaya began with research done here."}},
  sgbotanic_burkill: {p:"sgbotanic"},
  sgbotanic_swan: {p:"sgbotanic"},
  sgsciencecentre: {k:{zh:"科学馆", en:"Science centre"}, y:"1977", a:{zh:"Raymond Woo", en:"Raymond Woo"},
    d:{zh:"新加坡科学馆于1977年开馆，是亚洲最早的互动式科学中心之一。棱角分明的混凝土展厅由本地建筑师Raymond Woo设计，是粗野主义风格的代表；旁边的全天域电影院于1987年启用，在巨大的穹顶银幕上放映科普电影。",
       en:"Science Centre Singapore opened in 1977 as one of the first hands-on science centres in Asia. Its angular concrete halls, designed by local architect Raymond Woo, are a strong example of the Brutalist style. The neighbouring Omni-Theatre, opened in 1987, shows science films on a giant dome screen."}},
  sgsciencecentre_marquee: {p:"sgsciencecentre"},
  sgsciencecentre_arm: {p:"sgsciencecentre"},
  sgsciencecentre_omni: {p:"sgsciencecentre"},
  sghawpar: {k:{zh:"主题公园", en:"Theme park"}, y:"1937",
    d:{zh:"虎豹别墅由“虎标万金油”的创办人胡文虎、胡文豹兄弟于1937年兴建。园内有一千多座塑像和150多组立体场景，讲述中国民间故事、神话和道德寓言；最有名的“十殿阎王”展区以生动（也有些吓人）的方式描绘地府的惩罚。",
       en:"Haw Par Villa was created in 1937 by Aw Boon Haw and Aw Boon Par, the brothers behind Tiger Balm. More than 1,000 statues and over 150 dioramas tell Chinese folk tales, legends and moral lessons. Its most famous section, the Ten Courts of Hell, shows punishments in the underworld in vivid, and rather scary, detail."}}
});

// ---------------- Singapore sites (SITES.<key>) ----------------
Object.assign(window.LM_INFO, {
  "site:nus": {k:{zh:"大学校园", en:"University campus"}, y:"1905",
    d:{zh:"新加坡国立大学的历史可追溯至1905年创办的医学院，1980年由新加坡大学与南洋大学合并而成现名。肯特岗主校区沿山脊铺开，学院、宿舍、医院和研究机构以有顶走廊相连，南边还有自成一体的大学城。国大是亚洲排名最高的大学之一。",
       en:"The National University of Singapore traces its roots to a medical school founded in 1905, and took its present name in 1980 when the University of Singapore merged with Nanyang University. The Kent Ridge campus spreads along a hilly ridge, with faculties, halls, a hospital and research institutes linked by covered walkways, plus University Town to the south. NUS is one of Asia's top-ranked universities."}},
  "site:ntu": {k:{zh:"大学校园", en:"University campus"}, y:"1991",
    d:{zh:"南洋理工大学于1991年成立，前身是1981年创办的南洋理工学院，校园所在地正是1955年由民间捐资创办的南洋大学旧址。云南园里仍保留着南大当年的行政楼（今华裔馆）；托马斯·赫斯维克设计、形似一叠竹蒸笼的“学习中心”（The Hive）是校园最知名的新建筑。",
       en:"Nanyang Technological University was set up in 1991 from the Nanyang Technological Institute of 1981, on the grounds of Nanyang University, founded in 1955 with donations from the community. In Yunnan Garden the old Nantah administration building, now the Chinese Heritage Centre, still stands. Thomas Heatherwick's The Hive, which looks like a stack of bamboo steamer baskets, is the campus's best-known new building."}},
  "site:uss": {k:{zh:"主题乐园", en:"Theme park"}, y:"2010",
    d:{zh:"新加坡环球影城位于圣淘沙名胜世界内，2010年开幕，是东南亚第一座环球影城主题乐园。园区分为多个主题区，题材从好莱坞电影一直延伸到古埃及；入口处旋转的环球地球仪是最经典的打卡点，双轨对冲的“太空堡垒卡拉狄加”过山车也很有人气。",
       en:"Universal Studios Singapore opened in 2010 inside Resorts World Sentosa as the first Universal theme park in Southeast Asia. It is divided into themed zones inspired by films and places from Hollywood to ancient Egypt. The spinning Universal globe at the entrance is the classic photo spot, and the twin Battlestar Galactica roller coasters are among its best-known rides."}},
  "site:changiair": {k:{zh:"机场航站楼", en:"Airport terminals"}, y:"1981",
    d:{zh:"樟宜机场于1981年启用，建在新加坡东端填海和平整出的土地上，取代了巴耶利峇机场。一、二、三号航站楼分别于1981、1990和2008年启用，以空中轻轨相连，楼内遍布花园、艺术品和休闲设施，多次获评“世界最佳机场”。",
       en:"Changi Airport opened in 1981 on land reclaimed and cleared at the eastern tip of Singapore, replacing Paya Lebar Airport. Terminals 1, 2 and 3 opened in 1981, 1990 and 2008 and are linked by the Skytrain. Filled with gardens, art and places to relax, Changi has been named the world's best airport many times."}},
  "site:changit4": {k:{zh:"机场航站楼", en:"Airport terminal"}, y:"2017",
    d:{zh:"樟宜机场第四航站楼于2017年启用，以自助服务为核心：值机、托运、出入境和登机都可以通过自动化设备和人脸识别完成。楼内的“文化遗产区”重现了一排土生华人店屋的立面，并定时上演一段数字动画小剧场。",
       en:"Terminal 4 opened in 2017 and was built around self-service: travellers can check in, drop bags, clear immigration and board using automated machines and face recognition. Inside, the Heritage Zone recreates a row of Peranakan shophouse fronts that come alive with a short digital show."}},
  "site:changicargo": {k:{zh:"航空货运与维修区", en:"Air cargo and maintenance area"},
    d:{zh:"樟宜航空货运中心是机场的货运区，设有多座货运站和物流仓库，处理进出新加坡的航空货物，是区域重要的空运枢纽。旁边的大型机库用于飞机的检修与保养，支撑着新加坡发达的航空维修产业。",
       en:"The Changi Airfreight Centre is the airport's cargo zone, with freight terminals and logistics warehouses that handle air cargo in and out of Singapore, one of the region's key freight hubs. Next to it, large hangars are used to service and repair aircraft, part of Singapore's strong aircraft maintenance industry."}},
  "site:gardens": {k:{zh:"花园", en:"Garden"}, y:"2012", a:{zh:"格兰特景观事务所；威尔金森·艾尔（温室）", en:"Grant Associates; Wilkinson Eyre (conservatories)"},
    d:{zh:"滨海湾花园南花园于2012年开放，建在滨海湾的填海地上。18棵高25至50米的“超级树”外覆植物，可收集雨水，部分装有太阳能板，每晚还有灯光音乐秀。两座大型温室中，花穹是世界最大的玻璃温室之一，云雾林里则有一座约35米高、云雾缭绕的“山”和室内瀑布。",
       en:"Bay South garden opened in 2012 on reclaimed land at Marina Bay. Its 18 Supertrees, 25 to 50 metres tall and covered in plants, collect rainwater and some carry solar panels, and they light up for a nightly light-and-sound show. The Flower Dome is one of the largest glass greenhouses in the world, and the Cloud Forest wraps a 35-metre misty mountain with an indoor waterfall."}}
});

// ---------------- NUS Kent Ridge building labels ('site:nus:<en label>') ----------------
Object.assign(window.LM_INFO, {
  // Engineering (College of Design and Engineering)
  "site:nus:Engineering Block E1": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"E1是国大工程区沿工程路排开的核心楼群之一，内有教室、实验室和办公室。工程区如今属于设计与工程学院（CDE），该学院在2021年由原工程学院和设计与环境学院合并而成。",
       en:"E1 is one of the core blocks of the NUS engineering cluster along Engineering Drive, with classrooms, labs and offices. The area now belongs to the College of Design and Engineering (CDE), formed in 2021 by merging the Faculty of Engineering and the School of Design and Environment."}},
  "site:nus:Engineering Block E1A": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"E1A紧挨着E1，是工程区较早一批楼宇的扩建部分，主要用作教学和科研实验室。工程区的楼与楼之间以有顶走廊和天桥相连，学生下雨天也能在各楼之间穿行。",
       en:"E1A sits right next to E1 and is part of the extensions to the older engineering blocks, used mainly for teaching and research labs. Covered walkways and link bridges join the engineering buildings, so students can move between them even in heavy rain."}},
  "site:nus:Engineering Block E2": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"E2是工程区中段的教学与实验楼，与E1、E3等相邻楼宇连成一片。工程学科需要大量动手实验，这一带的楼宇里分布着各类实验室、工作坊和研讨室。",
       en:"E2 is a teaching and lab building in the middle of the engineering cluster, joined to neighbouring blocks such as E1 and E3. Engineering involves a lot of hands-on work, and the buildings here hold many labs, workshops and seminar rooms."}},
  "site:nus:Engineering Block E3": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"E3是工程区的主要教学楼之一，楼内有讲堂、教室和各系的实验设施。沿工程路一字排开的E字头楼群，是国大理工科学生日常上课和做项目的地方。",
       en:"E3 is one of the main teaching blocks in the engineering cluster, with lecture rooms, classrooms and departmental lab facilities. The row of 'E' blocks along Engineering Drive is where NUS engineering students spend most of their days in class and on projects."}},
  "site:nus:Engineering Block E3A": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"E3A位于工程区南侧，是E3的延伸楼宇，主要容纳研究实验室和教职员办公室。研究生和研究人员在这里开展项目，楼宇之间同样以有顶走廊相连。",
       en:"E3A stands on the southern side of the engineering cluster as an extension of E3, mainly housing research labs and staff offices. Graduate students and researchers carry out their projects here, and covered walkways link it to the blocks nearby."}},
  "site:nus:Engineering Block E4": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"E4是工程区中部的大型教学与科研楼，楼内有众多电子与计算相关的实验室。它与周边楼宇通过天桥相连，是工程区人流最多的地方之一。",
       en:"E4 is a large teaching and research building in the middle of the engineering cluster, with many labs for electronics and computing. Bridges link it to the blocks around it, and it is one of the busiest spots in the engineering area."}},
  "site:nus:Engineering Block E5": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"E5位于工程区北侧，靠近工程学院食堂Techno Edge，楼内主要是教学和化学、材料类实验室。课间时分，学生常从这里穿过有顶走廊去食堂或图书馆。",
       en:"E5 lies on the northern side of the engineering cluster near the Techno Edge canteen, with teaching rooms and labs for chemical and materials work. Between classes students often cut through its covered walkways to the canteen or the library."}},
  "site:nus:Information Technology Building (Computer Centre)": {k:{zh:"信息技术中心", en:"IT centre"},
    d:{zh:"信息技术大楼是国大计算机中心所在地，负责全校的网络、数据中心和信息系统。从选课系统到校园无线网络，许多看不见的数字服务都由这里支撑。",
       en:"The Information Technology Building is home to the NUS Computer Centre, which runs the university's network, data centres and information systems. Many invisible digital services, from course registration to campus Wi-Fi, are supported from here."}},
  "site:nus:Centre for English Language Communication (CELC)": {k:{zh:"教学中心", en:"Teaching centre"},
    d:{zh:"英语语言与传播中心负责国大的学术英语与沟通课程，帮助学生提升学术写作、演讲和专业沟通能力。许多一年级学生都会在这里上写作与沟通课。",
       en:"The Centre for English Language Communication runs NUS courses in academic English and communication, helping students improve their academic writing, presentations and professional communication. Many first-year students take their writing and communication classes here."}},
  "site:nus:SDE2 (College of Design and Engineering)": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"SDE2原属设计与环境学院，现归设计与工程学院，楼内有建筑与设计类专业的设计工作室和评图空间。深夜仍亮着灯的工作室，是设计系学生赶模型、赶图的日常写照。",
       en:"SDE2 belonged to the former School of Design and Environment and is now part of the College of Design and Engineering, with design studios and review spaces for architecture and design students. Studios lit up late at night are a familiar sight as students race to finish models and drawings."}},
  "site:nus:SDE1 (College of Design and Engineering)": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"SDE1是原设计与环境学院最早的楼宇之一，如今属于设计与工程学院，用于建筑、建成环境等专业的教学与研究。SDE楼群与工程区相邻，方便设计与工程两个领域的交流。",
       en:"SDE1 is one of the oldest buildings of the former School of Design and Environment and now serves the College of Design and Engineering for teaching and research in architecture and the built environment. The SDE buildings sit next to the engineering cluster, making it easy for design and engineering to mix."}},
  "site:nus:SDE3 (College of Design and Engineering)": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"SDE3与SDE1、SDE2相邻，设有教室、研究室和办公室，主要服务建成环境与设计相关的课程。几座SDE楼之间的庭院和走廊，是学生展示作品和讨论的地方。",
       en:"SDE3 stands beside SDE1 and SDE2, with classrooms, research rooms and offices that mainly serve built-environment and design courses. The courtyards and corridors between the SDE buildings are where students show their work and discuss ideas."}},
  "site:nus:SDE4 — net-zero energy building": {k:{zh:"零能耗教学楼", en:"Net-zero energy building"}, y:"2019", a:{zh:"Serie + Multiply 建筑事务所与盛裕集团", en:"Serie + Multiply Architects with Surbana Jurong"},
    d:{zh:"SDE4于2019年启用，是新加坡第一座新建的净零能耗建筑，屋顶的大面积太阳能板所发的电足以抵消大楼的能耗。它采用混合制冷系统，把较高温度的冷空气和吊扇结合，许多空间开放通风，是热带绿色建筑的示范。",
       en:"Opened in 2019, SDE4 was Singapore's first newly built net-zero energy building: the large solar roof produces as much electricity as the building uses. A hybrid cooling system supplies air at a higher temperature plus ceiling fans, and many spaces are open to breezes, making it a model of green design for the tropics."}},
  "site:nus:Engineering Block E7": {k:{zh:"教学科研楼", en:"Teaching and research building"},
    d:{zh:"E7是工程区东侧较新的楼宇，主要用于科研实验室和研究生的工作空间。它和E6、E8等楼一起构成工程区向东扩展的部分。",
       en:"E7 is one of the newer buildings on the eastern side of the engineering cluster, used mostly for research labs and graduate student workspaces. Together with E6 and E8 it forms the eastward growth of the engineering area."}},
  "site:nus:Engineering Block E6 (NanoFab)": {k:{zh:"科研楼", en:"Research building"},
    d:{zh:"E6楼内设有纳米加工设施（NanoFab），配备洁净室，可进行芯片和微纳器件的制造与测试。洁净室对灰尘和振动要求极高，研究人员必须穿上全身防护服才能进入。",
       en:"E6 houses the NanoFab facility, with clean rooms for making and testing chips and tiny devices at the micro and nano scale. Clean rooms must be almost free of dust and vibration, so researchers wear full-body suits to go inside."}},
  "site:nus:Engineering Block E8": {k:{zh:"教学科研楼", en:"Teaching and research building"},
    d:{zh:"E8是工程区较新的楼宇之一，提供实验室、项目工作室和协作空间，方便学生以小组形式开展工程设计项目。宽敞的公共空间也常用来展示学生作品。",
       en:"E8 is one of the newer engineering buildings, with labs, project studios and shared spaces where students work in teams on engineering design projects. Its open common areas are often used to show off student work."}},
  "site:nus:T-Lab (Temasek Laboratories)": {k:{zh:"研究机构", en:"Research institute"},
    d:{zh:"淡马锡实验室是设在国大的国防科技研究机构，在国防部门的支持下开展基础与应用研究，领域涉及电磁、航空和材料等。这里的研究成果也会转化到民用科技上。",
       en:"Temasek Laboratories at NUS is a defence-science research institute supported by Singapore's defence sector, carrying out basic and applied research in areas such as electromagnetics, aerospace and materials. Some of its results also find their way into civilian technology."}},
  "site:nus:Engineering Block EA": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"EA位于工程区西南角，是工程区里资历较老的楼宇之一，楼内有大型实验厅和教学空间。宽大的实验厅可以容纳较重的设备和大型实验装置。",
       en:"EA stands at the south-west corner of the engineering cluster and is one of its older buildings, with large lab halls and teaching spaces. The big halls can hold heavy equipment and large test rigs."}},
  "site:nus:Engineering Workshop EW1": {k:{zh:"工程工场", en:"Engineering workshop"},
    d:{zh:"工程工场EW1是学生动手制作的地方，配有机床、焊接和加工设备。从课程项目到学生方程式赛车等竞赛作品，许多零件都在这样的工场里被切割、打磨和组装出来。",
       en:"Engineering Workshop EW1 is where students build things with their hands, with machine tools and equipment for cutting, welding and shaping. Parts for course projects and student competition entries are cut, finished and assembled in workshops like this."}},
  "site:nus:Techno Edge (canteen)": {k:{zh:"食阁", en:"Canteen"},
    d:{zh:"Techno Edge是工程区的食阁，供应各式本地和亚洲美食，价格实惠。午饭时间这里挤满了工程和设计专业的学生，也是课后讨论项目的热门据点。",
       en:"Techno Edge is the engineering cluster's canteen, serving affordable local and Asian food. At lunchtime it fills up with engineering and design students, and it is also a popular place to talk over projects after class."}},

  // Arts, music, museum, central facilities
  "site:nus:University Cultural Centre": {k:{zh:"文化中心", en:"Cultural centre"},
    d:{zh:"大学文化中心是国大的大型演艺场馆，主礼堂可容纳一千多名观众，用于音乐会、戏剧和讲座。每年的毕业典礼也在这里举行，是许多国大学生难忘的地方。",
       en:"The University Cultural Centre is NUS's main performing arts venue, with a hall seating well over a thousand people for concerts, plays and talks. The university's commencement ceremonies are held here every year, making it a memorable place for many graduates."}},
  "site:nus:Yong Siew Toh Conservatory of Music": {k:{zh:"音乐学院", en:"Music conservatory"},
    d:{zh:"杨秀桃音乐学院是新加坡第一所音乐学院，由国大与美国约翰·霍普金斯大学皮博迪音乐学院合作创办。学院设有音乐厅和众多琴房，经常举办免费或低价的学生音乐会。",
       en:"The Yong Siew Toh Conservatory is Singapore's first conservatory of music, founded by NUS in partnership with the Peabody Institute of Johns Hopkins University. It has a concert hall and many practice rooms, and often holds free or low-cost student concerts."}},
  "site:nus:Lee Kong Chian Natural History Museum": {k:{zh:"自然历史博物馆", en:"Natural history museum"}, y:"2015",
    d:{zh:"李光前自然历史博物馆于2015年开馆，收藏东南亚的动植物标本，是区域内重要的生物多样性研究机构。镇馆之宝是三具几乎完整的蜥脚类恐龙骨架，外墙像一块长满植物的巨岩。",
       en:"The Lee Kong Chian Natural History Museum opened in 2015 and holds specimens of Southeast Asian plants and animals, making it a key centre for biodiversity research in the region. Its stars are three nearly complete sauropod dinosaur skeletons, and the building looks like a huge rock covered in plants."}},
  "site:nus:Central Library": {k:{zh:"图书馆", en:"Library"},
    d:{zh:"中央图书馆是国大规模最大的图书馆，收藏人文、社科、理工等各领域的书籍与资料，也设有中文图书馆。考试季时，这里的自修空间一座难求。",
       en:"The Central Library is the largest library at NUS, with books and materials across the humanities, social sciences, science and engineering, as well as a Chinese library. During exam season its study spaces are very hard to find."}},
  "site:nus:Yusof Ishak House": {k:{zh:"学生活动中心", en:"Student activity centre"},
    d:{zh:"尤索夫伊萨大厦以新加坡首任总统尤索夫·伊萨命名，是学生会和众多学生社团的活动据点。社团招新、排练和各类学生活动常在这里进行。",
       en:"Yusof Ishak House is named after Yusof Ishak, Singapore's first President, and is a base for the students' union and many student clubs. Club recruitment, rehearsals and all kinds of student events often take place here."}},
  "site:nus:Faculty of Arts and Social Sciences (AS1)": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"AS1是人文与社会科学学院（FASS）的主要楼宇之一。FASS是国大规模最大的学院之一，涵盖语言、历史、哲学、经济、心理等众多学科，2021年起与理学院一同归入人文与科学学院。",
       en:"AS1 is one of the main buildings of the Faculty of Arts and Social Sciences (FASS), one of the largest faculties at NUS, covering languages, history, philosophy, economics, psychology and more. Since 2021 FASS and the Faculty of Science have been grouped under the College of Humanities and Sciences."}},
  "site:nus:AS7 — Shaw Foundation Building": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"AS7邵氏基金楼以捐建的邵氏基金命名，属于人文与社会科学学院，楼内有教室、研讨室和学系办公室。它位于肯特岗西侧的FASS楼群中，与AS1、AS8等楼相连。",
       en:"AS7, the Shaw Foundation Building, is named after the Shaw Foundation, which supported its construction. It belongs to the Faculty of Arts and Social Sciences, with classrooms, seminar rooms and department offices, and sits among the FASS buildings on the western side of Kent Ridge, linked to AS1 and AS8."}},
  "site:nus:AS8 — Faculty of Arts and Social Sciences": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"AS8是人文与社会科学学院的教学楼，设有多个学系办公室、研讨室和研究中心。FASS的楼群依坡而建，楼宇之间以走廊和阶梯相连，是文科学生上课的主要区域。",
       en:"AS8 is a teaching building of the Faculty of Arts and Social Sciences, with department offices, seminar rooms and research centres. The FASS buildings are built into the slope and joined by corridors and stairways, forming the main area where arts students attend classes."}},
  "site:nus:Mochtar Riady Building (NUS Business School)": {k:{zh:"商学院大楼", en:"Business school building"},
    d:{zh:"李文正大楼是国大商学院的主楼，以印度尼西亚银行家、力宝集团创办人李文正命名。楼内有阶梯教室、案例讨论室和研究中心，培养本科、硕士和MBA学生。",
       en:"The Mochtar Riady Building is the main home of NUS Business School, named after Indonesian banker Mochtar Riady, founder of the Lippo Group. It has tiered lecture rooms, case-discussion rooms and research centres for undergraduate, master's and MBA students."}},
  "site:nus:NUS Business School (BIZ2)": {k:{zh:"商学院大楼", en:"Business school building"},
    d:{zh:"BIZ2是商学院的第二座主要楼宇，与李文正大楼和韩瑞生纪念图书馆相邻，楼内有教室、学系办公室和学生活动空间。商学院区域位于肯特岗北坡，靠近肯特岗路。",
       en:"BIZ2 is the second main building of NUS Business School, next to the Mochtar Riady Building and the Hon Sui Sen Memorial Library, with classrooms, department offices and student spaces. The business school area sits on the northern slope of Kent Ridge, near Kent Ridge Road."}},
  "site:nus:Hon Sui Sen Memorial Library": {k:{zh:"图书馆", en:"Library"},
    d:{zh:"韩瑞生纪念图书馆是国大的商科图书馆，以新加坡前财政部长韩瑞生命名，他在1970年至1983年间主管国家财政。馆内收藏商业、管理和金融方面的书籍与数据库。",
       en:"The Hon Sui Sen Memorial Library is the NUS business library, named after Hon Sui Sen, Singapore's Minister for Finance from 1970 to 1983. It holds books and databases on business, management and finance."}},
  "site:nus:School of Computing (COM3)": {k:{zh:"教学科研楼", en:"Teaching and research building"},
    d:{zh:"COM3是计算机学院较新的楼宇，提供实验室、教室和开放式的学习空间。计算机学院是亚洲领先的计算机科学院系之一，COM楼群是程序员和研究者通宵写代码的地方。",
       en:"COM3 is one of the newer buildings of the School of Computing, with labs, classrooms and open study spaces. The school is one of Asia's leading computer science departments, and the COM buildings are where students and researchers code late into the night."}},
  "site:nus:School of Computing (COM1)": {k:{zh:"教学科研楼", en:"Teaching and research building"},
    d:{zh:"COM1是计算机学院的主楼之一，设有教室、计算机实验室和教职员办公室。计算机学院开设计算机科学、信息系统、商业分析等课程，许多学生在这里完成课程项目和编程竞赛训练。",
       en:"COM1 is one of the main buildings of the School of Computing, with classrooms, computer labs and staff offices. The school teaches computer science, information systems, business analytics and more, and many students work on course projects and coding contest practice here."}},
  "site:nus:i3 Building": {k:{zh:"研究大楼", en:"Research building"},
    d:{zh:"i3创新大楼位于校园东北的研究区，楼内设有多个研究中心和创新相关单位。这一带聚集着研究机构和科技公司，是国大连接学术研究与产业的区域之一。",
       en:"The i3 Building stands in the research area at the north-east of the campus and houses several research centres and innovation units. This part of campus gathers research institutes and technology firms, linking university research with industry."}},
  "site:nus:Innovation 4.0 (i4.0)": {k:{zh:"研究大楼", en:"Research building"},
    d:{zh:"创新4.0大楼是国大较新的跨学科研究大楼，聚焦数字科技与智慧国家相关的研究。名字中的“4.0”呼应第四次工业革命，楼内有开放的实验与协作空间。",
       en:"Innovation 4.0 is one of the newer NUS research buildings, bringing together different fields to work on digital technology and Smart Nation projects. The '4.0' in its name refers to the Fourth Industrial Revolution, and it has open spaces for lab work and teamwork."}},
  "site:nus:Shaw Foundation Alumni House": {k:{zh:"校友会所", en:"Alumni clubhouse"},
    d:{zh:"邵氏基金会校友会所是国大校友的聚会场所，设有餐厅、会议室和活动空间。毕业生回校聚会、举办讲座和交流活动时常在这里进行。",
       en:"The Shaw Foundation Alumni House is a meeting place for NUS graduates, with restaurants, meeting rooms and event spaces. Alumni gatherings, talks and networking events are often held here, keeping graduates connected to the university."}},
  "site:nus:Kent Ridge Guild House": {k:{zh:"会所", en:"Clubhouse"},
    d:{zh:"肯特岗会所是国大校友会（NUSS）的会所之一，设有餐厅和社交设施。它坐落在绿意环绕的山坡上，是校友和教职员聚餐、举办活动的地方。",
       en:"Kent Ridge Guild House is one of the clubhouses of the NUS Society (NUSS), the graduates' association, with restaurants and social facilities. Set on a leafy slope, it is a place where alumni and staff meet for meals and events."}},
  "site:nus:The Ridge (NUS campus hotel)": {k:{zh:"校园酒店", en:"Campus hotel"},
    d:{zh:"The Ridge是位于肯特岗山坡上的校园酒店，为来访的学者、讲者和参加会议的宾客提供住宿。住在这里，可以步行前往大学文化中心和人文、商学院等教学区。",
       en:"The Ridge is a campus hotel on the slopes of Kent Ridge, providing rooms for visiting scholars, speakers and conference guests. Staying here puts the University Cultural Centre and the arts and business areas within walking distance."}},
  "site:nus:The Deck (canteen)": {k:{zh:"食阁", en:"Canteen"},
    d:{zh:"The Deck是人文与社会科学学院旁的食阁，提供多种本地和国际风味的平价餐食。它是文科学生吃饭、聊天和课间休息的主要去处，午餐时分十分热闹。",
       en:"The Deck is the canteen beside the Faculty of Arts and Social Sciences, offering affordable local and international food. It is the main place for arts students to eat, chat and rest between classes, and it gets very busy at lunchtime."}},

  // Science-park side / institutes
  "site:nus:Singapore Synchrotron Light Source": {k:{zh:"大型科研装置", en:"Research facility"},
    d:{zh:"新加坡同步辐射光源是一台电子储存环装置：高速电子在环中绕行时会发出从红外到X射线的强光，用于研究材料结构和微纳加工。它是新加坡少有的大型科学装置之一。",
       en:"The Singapore Synchrotron Light Source is an electron storage ring: as fast electrons circle inside it, they give off intense light from infrared to X-rays, which scientists use to study materials and make tiny structures. It is one of Singapore's few large-scale science facilities."}},
  "site:nus:Central Water Tank": {k:{zh:"水塔", en:"Water tower"},
    d:{zh:"中央水塔立在肯特岗的高处，是校园里远远就能望见的地标之一。水塔利用地势高差向周边楼宇供水，这种做法在新加坡的老校区和住宅区很常见。",
       en:"The Central Water Tank stands high on Kent Ridge and is one of the campus landmarks you can spot from far away. Water towers like this use height to supply water to the buildings around them, a common sight in older campuses and estates in Singapore."}},
  "site:nus:Technology Centre for Offshore and Marine, Singapore (TCOMS)": {k:{zh:"研究中心", en:"Research centre"},
    d:{zh:"新加坡海洋与离岸技术中心是国家级的海事与海洋工程研发中心，拥有一座大型深水试验水池，可模拟海浪和水流，测试船舶与海上平台的缩尺模型。它支撑着新加坡的港口与海事产业。",
       en:"TCOMS is a national research centre for marine and offshore engineering. Its large deep-water test basin can create waves and currents to test scale models of ships and offshore platforms, supporting Singapore's port and maritime industries."}},
  "site:nus:Ventus (University Campus Infrastructure)": {k:{zh:"办公楼", en:"Office building"},
    d:{zh:"Ventus是国大校园基础设施部门的办公楼，负责校园的规划、建设、维护和可持续发展。校园里的道路、楼宇、绿化和节能项目，很多都由这里统筹。",
       en:"Ventus is the office of University Campus Infrastructure, the NUS unit in charge of planning, building, maintaining and greening the campus. Many of the campus's roads, buildings, landscapes and energy-saving projects are managed from here."}},
  "site:nus:ISEAS–Yusof Ishak Institute": {k:{zh:"研究机构", en:"Research institute"},
    d:{zh:"尤索夫伊萨东南亚研究院成立于1968年，是专门研究东南亚政治、经济和社会的智库，2015年以新加坡首任总统尤索夫·伊萨的名字更名。研究院的出版物和图书馆在区域研究领域很有影响力。",
       en:"The ISEAS–Yusof Ishak Institute was set up in 1968 as a research centre on the politics, economics and society of Southeast Asia, and was renamed in 2015 after Singapore's first President, Yusof Ishak. Its publications and library are highly regarded in regional studies."}},
  "site:nus:Institute of Systems Science": {k:{zh:"研究与培训机构", en:"Institute"},
    d:{zh:"系统科学院（NUS-ISS）成立于1981年，专注于信息技术与数字化的专业培训和研究生课程，面向在职人士。几十年来，它为新加坡培养了大批信息技术人才。",
       en:"The Institute of Systems Science (NUS-ISS) was founded in 1981 and focuses on professional training and graduate courses in information technology and digital skills for working adults. Over the decades it has trained a large number of Singapore's IT professionals."}},
  "site:nus:University Hall": {k:{zh:"行政大楼", en:"Administration building"},
    d:{zh:"大学堂是国大的行政中心，校长办公室和许多校级管理部门都设在这里。它位于肯特岗校区的中部，是学校决策和对外接待的重要场所。",
       en:"University Hall is the administrative centre of NUS, housing the President's Office and many university-level departments. It stands in the middle of the Kent Ridge campus and is where key decisions are made and official visitors are received."}},

  // Medicine and science
  "site:nus:MD1 – Tahir Foundation Building": {k:{zh:"医学院大楼", en:"Medical school building"},
    d:{zh:"MD1大楼属于杨潞龄医学院，以捐款支持医学教育的印度尼西亚慈善家达哈尔的基金会命名。楼内有教学设施、研究实验室和学系办公室，靠近国立大学医院，方便教学与临床结合。",
       en:"MD1, the Tahir Foundation Building, belongs to the Yong Loo Lin School of Medicine and is named after the foundation of Indonesian philanthropist Tahir, a supporter of medical education. It holds teaching facilities, research labs and department offices close to the National University Hospital."}},
  "site:nus:Centre for Translational Medicine (MD6)": {k:{zh:"医学研究中心", en:"Medical research centre"},
    d:{zh:"转化医学中心（MD6）致力于把实验室里的发现转化为可以用于病人的诊断和治疗。研究人员和临床医生在这里合作，研究癌症、心血管疾病和传染病等课题。",
       en:"The Centre for Translational Medicine (MD6) works to turn discoveries made in the lab into tests and treatments for patients. Scientists and doctors work side by side here on topics such as cancer, heart disease and infectious diseases."}},
  "site:nus:Clinical Research Centre (MD11)": {k:{zh:"临床研究中心", en:"Clinical research centre"},
    d:{zh:"临床研究中心（MD11）为医学院和医院的临床研究提供实验室和研究空间。它靠近国立大学医院，研究人员可以把临床观察与实验研究紧密结合起来。",
       en:"The Clinical Research Centre (MD11) provides labs and research space for clinical studies by the medical school and hospital. Being close to the National University Hospital lets researchers link what they see in patients with work in the lab."}},
  "site:nus:Centre for Life Sciences": {k:{zh:"生命科学研究中心", en:"Life sciences centre"},
    d:{zh:"生命科学中心汇集了生物学、医学和工程等多个领域的研究团队，研究方向包括细胞生物学、神经科学和生物医学工程。跨领域的研究团队在同一屋檐下，便于合作。",
       en:"The Centre for Life Sciences brings together research teams from biology, medicine and engineering, working on topics such as cell biology, neuroscience and biomedical engineering. Having different fields under one roof makes teamwork easier."}},
  "site:nus:Medicine+Science Library": {k:{zh:"图书馆", en:"Library"},
    d:{zh:"医学与理学图书馆服务医学、理学等学科的师生，收藏专业书籍、期刊和数据库，并提供自修和小组讨论空间。它位于理学院和医学院之间，方便两边的学生使用。",
       en:"The Medicine+Science Library serves students and staff in medicine and science, with specialist books, journals and databases, plus space for quiet study and group work. It sits between the science and medical areas, handy for students from both."}},
  "site:nus:S9 Wet Science Building": {k:{zh:"实验楼", en:"Laboratory building"},
    d:{zh:"S9是理学院的“湿实验”大楼，主要容纳化学、生物等需要用到液体和试剂的实验室。这类实验室对通风和安全设施要求很高，因此专门集中在这栋楼里。",
       en:"S9 is the Faculty of Science's 'wet lab' building, mainly for chemistry and biology labs that work with liquids and chemicals. Such labs need strong ventilation and safety systems, so they are grouped in this purpose-built block."}},
  "site:nus:Faculty of Science (S16)": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"S16是理学院的教学楼之一，设有教室、实验室和学系办公室。理学院的S字头楼群分布在肯特岗东侧，学生在这里修读数学、物理、化学、生命科学等课程。",
       en:"S16 is one of the Faculty of Science teaching blocks, with classrooms, labs and department offices. The 'S' buildings spread across the eastern side of Kent Ridge, where students take courses in mathematics, physics, chemistry and the life sciences."}},
  "site:nus:Faculty of Science (S17)": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"S17是理学院的教学楼，楼内有教室、电脑室和教职员办公室。它与S16等楼相连，是理科学生上课、做习题和找教授答疑的地方。",
       en:"S17 is a Faculty of Science building with classrooms, computer rooms and staff offices. Linked to S16 and its neighbours, it is where science students attend classes, work through problem sets and meet their professors."}},
  "site:nus:Lee Wee Kheng Building (S1A)": {k:{zh:"教学楼", en:"Academic building"},
    d:{zh:"李伟庆大楼（S1A）是理学院的楼宇之一，设有教学和科研空间。理学院的楼宇大多以字母S加编号命名，S1A位于理学院区域靠近大学堂的一侧。",
       en:"The Lee Wee Kheng Building (S1A) is one of the Faculty of Science buildings, with space for teaching and research. Most science buildings are named with an 'S' and a number, and S1A sits on the side of the science area closest to University Hall."}},
  "site:nus:Lim Seng Tjoe Lecture Theatre (LT27)": {k:{zh:"讲堂", en:"Lecture theatre"},
    d:{zh:"林生秩讲堂（LT27）是理学院区域的大型阶梯讲堂，可容纳数百名学生同时上课。大一的基础课和各类公开讲座常在这里举行。",
       en:"The Lim Seng Tjoe Lecture Theatre (LT27) is a large tiered lecture hall in the science area that can seat hundreds of students at once. First-year core lectures and public talks are often held here."}},
  "site:nus:Frontier canteen": {k:{zh:"食阁", en:"Canteen"},
    d:{zh:"Frontier是理学院区域的食阁，供应各式本地小吃和快餐，价格亲民。理科和医科学生常在这里吃饭、复习，或在实验间隙稍作休息。",
       en:"Frontier is the canteen in the science area, serving local favourites and quick meals at student-friendly prices. Science and medical students often eat, study or take a break between lab sessions here."}},

  // National University Hospital
  "site:nus:National University Hospital": {k:{zh:"医院", en:"Hospital"},
    d:{zh:"国立大学医院于1985年启用，是新加坡的大学附属医院，兼负医疗、教学和研究三项任务。它是国大医学院和牙医学院学生实习的主要医院，也提供多种专科和急诊服务。",
       en:"The National University Hospital opened in 1985 as Singapore's university teaching hospital, combining patient care, teaching and research. It is the main training hospital for NUS medical and dental students and offers a wide range of specialist and emergency services."}},
  "site:nus:NUH Medical Centre": {k:{zh:"专科医疗中心", en:"Specialist medical centre"},
    d:{zh:"国大医院医疗中心是国立大学医院的专科门诊大楼，集中了众多专科诊所、检查和治疗设施。病人可以在同一栋楼里完成看诊、检验和取药，减少来回奔波。",
       en:"The NUH Medical Centre is the National University Hospital's specialist outpatient building, bringing many specialist clinics, tests and treatments together. Patients can see doctors, get tests done and collect medicine in one building, saving trips around the campus."}},
  "site:nus:NUHS Tower Block": {k:{zh:"医院大楼", en:"Hospital building"},
    d:{zh:"国大卫生系统大楼属于国立大学卫生系统（NUHS），容纳诊所、医疗服务和行政办公室。NUHS把国立大学医院与国大的医学、牙医和公共卫生学院联系在一起。",
       en:"The NUHS Tower Block belongs to the National University Health System (NUHS) and houses clinics, medical services and offices. NUHS links the National University Hospital with the NUS schools of medicine, dentistry and public health."}},
  "site:nus:Kent Ridge Wing (NUH)": {k:{zh:"医院翼楼", en:"Hospital wing"},
    d:{zh:"肯特岗翼楼是国立大学医院的病房与医疗大楼之一，设有住院病房和多种医疗设施。它与主楼和其他医疗大楼相连，组成校园东端的医院园区。",
       en:"The Kent Ridge Wing is one of the National University Hospital's ward and treatment buildings, with inpatient wards and medical facilities. It connects to the main hospital and other medical buildings, forming the hospital campus at the eastern end of the grounds."}},
  "site:nus:National University Centre for Oral Health": {k:{zh:"口腔医疗中心", en:"Dental centre"},
    d:{zh:"国大口腔健康中心是集口腔医疗、教学与研究于一体的专科中心，也是国大牙医学院学生的主要培训场所。中心为公众提供从基础护理到复杂治疗的各类牙科服务。",
       en:"The National University Centre for Oral Health combines dental care, teaching and research, and is the main training place for NUS dental students. It offers the public a full range of dental services, from basic care to complex treatment."}},

  // Research park and institutes (north-east)
  "site:nus:Temasek Life Sciences Laboratory": {k:{zh:"研究机构", en:"Research institute"},
    d:{zh:"淡马锡生命科学研究院成立于2002年，专注于植物和微生物生物学等研究，成果应用于农业和生物技术。它位于国大校园内，与大学在研究和人才培养上紧密合作。",
       en:"Temasek Life Sciences Laboratory was set up in 2002 to study plant and microbial biology, with results used in agriculture and biotechnology. It is located on the NUS campus and works closely with the university on research and training."}},
  "site:nus:NUS Enterprise Incubator": {k:{zh:"创业孵化中心", en:"Start-up incubator"},
    d:{zh:"国大企业孵化中心为初创企业提供办公空间、导师指导和资源对接，帮助学生和研究人员把创意和科研成果变成公司。它是国大创业生态的一部分。",
       en:"The NUS Enterprise Incubator gives start-ups office space, mentoring and connections, helping students and researchers turn ideas and research into companies. It is part of the wider NUS start-up ecosystem."}},
  "site:nus:Energy Studies Institute": {k:{zh:"研究机构", en:"Research institute"},
    d:{zh:"能源研究所成立于2007年，是国大专注能源政策与经济的研究机构，研究课题涵盖能源安全、气候变化与能源转型。它为政府和业界提供研究分析和政策建议。",
       en:"The Energy Studies Institute was founded in 2007 as the NUS research institute on energy policy and economics, covering energy security, climate change and the energy transition. It provides research and policy advice to government and industry."}},
  "site:nus:Asia-Europe Foundation": {k:{zh:"国际组织", en:"International organisation"},
    d:{zh:"亚欧基金会成立于1997年，总部设在新加坡，是亚欧会议（ASEM）框架下唯一的常设机构。它通过文化、教育和公共卫生等交流项目，增进亚洲与欧洲之间的相互了解。",
       en:"The Asia-Europe Foundation was set up in 1997 and is based in Singapore. It is the only permanent institution of the Asia-Europe Meeting (ASEM), running exchanges in culture, education, public health and more to build understanding between Asia and Europe."}},

  // University Town and nearby
  "site:nus:Cinnamon College": {k:{zh:"住宿书院", en:"Residential college"},
    d:{zh:"肉桂书院是大学城的住宿书院之一，长期是国大“大学学者计划”（USP）的大本营。学生在这里同住、同学，书院课程与宿舍生活结合，强调跨学科学习。",
       en:"Cinnamon College is one of the residential colleges in University Town and was long the home of the NUS University Scholars Programme (USP). Students live and study together here, with college courses tied to residential life and an emphasis on learning across disciplines."}},
  "site:nus:University Sports Centre": {k:{zh:"体育中心", en:"Sports centre"},
    d:{zh:"大学体育中心设有体育馆、游泳池和户外运动场地，是国大校队训练和学生日常锻炼的主要场所。校内运动会和各类比赛也常在这里举行。",
       en:"The University Sports Centre has sports halls, a swimming pool and outdoor fields, and is the main place for NUS varsity teams to train and for students to keep fit. Inter-faculty games and other competitions are often held here."}},
  "site:nus:College of Alice & Peter Tan": {k:{zh:"住宿书院", en:"Residential college"},
    d:{zh:"爱丽丝与彼得·陈书院是大学城的住宿书院之一，以社区参与为特色，鼓励学生通过服务项目了解和关怀社会。书院以捐资人陈氏夫妇的名字命名。",
       en:"The College of Alice & Peter Tan is one of the residential colleges in University Town, known for its focus on community engagement: students learn about society through service projects. It is named after its donors, Alice and Peter Tan."}},
  "site:nus:Town Plaza": {k:{zh:"大学城广场", en:"Campus plaza"},
    d:{zh:"大学城广场是大学城的生活中心之一，设有餐饮、商店和休闲设施，学生常在这里吃饭、买东西和约见朋友。周边的书院和学习空间让这里从早到晚都很热闹。",
       en:"Town Plaza is one of the hubs of University Town, with places to eat, shops and spaces to relax, where students grab meals, run errands and meet friends. With colleges and study spaces all around, it stays lively from morning to night."}},
  "site:nus:Education Resource Centre": {k:{zh:"学习中心", en:"Learning centre"},
    d:{zh:"教育资源中心是大学城的学习大楼，提供大量自修和小组讨论空间，许多区域全天开放。考试季时，这里常常通宵灯火通明。",
       en:"The Education Resource Centre is University Town's study building, with lots of space for quiet study and group work, much of it open around the clock. In exam season its lights often stay on all night."}},
  "site:nus:CREATE — Campus for Research Excellence and Technological Enterprise": {k:{zh:"国际研究园区", en:"International research campus"},
    d:{zh:"CREATE是由新加坡国家研究基金会设立的国际研究园区，邀请世界知名大学在此设立研究中心，与本地大学合作开展可持续发展、城市、健康等领域的研究。",
       en:"CREATE is an international research campus set up by Singapore's National Research Foundation. Leading universities from around the world run research centres here, working with local universities on sustainability, cities, health and other topics."}},
  "site:nus:Residential College 4 (RC4)": {k:{zh:"住宿书院", en:"Residential college"},
    d:{zh:"第四住宿书院（RC4）是大学城的住宿书院之一，以“系统思维”为特色，书院课程引导学生用系统的方法看待复杂的社会与环境问题。",
       en:"Residential College 4 (RC4) is one of the residential colleges in University Town. Its theme is systems thinking, and its courses teach students to look at complex social and environmental problems as connected systems."}},
  "site:nus:MPSH 1–4 (Multi-Purpose Sports Halls)": {k:{zh:"多用途体育馆", en:"Sports halls"},
    d:{zh:"多用途体育馆1至4号平时用于羽毛球、篮球等室内运动，到了考试季则摆满桌椅，变成大型考场。对许多国大学生来说，这里既是球场，也是期末考的“战场”。",
       en:"Multi-Purpose Sports Halls 1 to 4 are used for indoor sports such as badminton and basketball, but in exam season they fill with rows of desks and become large exam halls. For many NUS students they are both a sports venue and a final-exam battleground."}},
  "site:nus:Stephen Riady Centre": {k:{zh:"大学城中心", en:"Campus centre"},
    d:{zh:"斯蒂芬·利雅迪中心是大学城的核心建筑之一，内有餐饮、学习空间、活动室和体育设施。它以印度尼西亚企业家利雅迪命名，是大学城学生生活的重要据点。",
       en:"The Stephen Riady Centre is one of the core buildings of University Town, with food outlets, study spaces, activity rooms and sports facilities. Named after Indonesian businessman Stephen Riady, it is a key part of student life in University Town."}},
  "site:nus:Singapore Wind Tunnel Facility": {k:{zh:"科研设施", en:"Research facility"},
    d:{zh:"新加坡风洞设施供空气动力学与风工程研究使用，可以测试建筑、桥梁、车辆等缩尺模型在风中的表现。在高楼林立的新加坡，了解风荷载对结构设计非常重要。",
       en:"The Singapore Wind Tunnel Facility is used for aerodynamics and wind engineering research, testing how scale models of buildings, bridges and vehicles behave in moving air. In a city full of towers like Singapore, understanding wind loads is vital for structural design."}},
  "site:nus:NUS College (former Yale-NUS campus)": {k:{zh:"住宿书院校园", en:"Residential college campus"},
    d:{zh:"这片校园原属耶鲁-国大学院，这所文理学院于2011年创办，校园于2015年启用，最后一届学生在2025年毕业。校园由三座围绕庭院的住宿书院和教学楼组成，如今由国大书院等单位使用。",
       en:"This campus belonged to Yale-NUS College, a liberal arts college founded in 2011; the campus opened in 2015 and the last class graduated in 2025. Built around courtyards with three residential colleges and teaching buildings, it is now used by NUS College and other units."}},
  "site:nus:MPSH 5 & 6": {k:{zh:"多用途体育馆", en:"Sports halls"},
    d:{zh:"多用途体育馆5号和6号与1至4号相邻，同样用于室内运动、活动和大型考试。体育馆一带靠近大学体育中心，是校园运动设施最集中的区域。",
       en:"Multi-Purpose Sports Halls 5 and 6 sit next to halls 1 to 4 and are likewise used for indoor sports, events and large exams. The area is close to the University Sports Centre and has the campus's largest group of sports facilities."}},
  "site:nus:Tembusu College": {k:{zh:"住宿书院", en:"Residential college"},
    d:{zh:"坦布苏书院是大学城最早的住宿书院之一，以新加坡常见的本土树种“坦布苏树”命名。书院以小班研讨课和丰富的书院生活为特色，强调跨学科的思考与交流。",
       en:"Tembusu College is one of the first residential colleges in University Town, named after the tembusu, a tree native to Singapore. It is known for small seminar classes and a rich college life that encourages thinking and talking across disciplines."}},
  "site:nus:Ngee Ann Kongsi Auditorium": {k:{zh:"礼堂", en:"Auditorium"},
    d:{zh:"义安公司礼堂位于大学城，以捐资支持的潮州人社团义安公司命名，用于讲座、演出和大型活动。大学城的许多书院活动和公开讲座都在这里举行。",
       en:"The Ngee Ann Kongsi Auditorium in University Town is named after the Ngee Ann Kongsi, the Teochew community foundation that supported it, and is used for lectures, performances and big events. Many college events and public talks in University Town are held here."}},
  "site:nus:University Health Centre": {k:{zh:"保健中心", en:"Health centre"},
    d:{zh:"大学保健中心为国大学生和教职员提供门诊、健康检查和心理辅导等服务。学生生病或需要倾诉时，这里通常是第一站。",
       en:"The University Health Centre provides NUS students and staff with clinic visits, health checks and counselling. It is usually the first stop for students who feel unwell or need someone to talk to."}},
  "site:nus:NUS Staff Club": {k:{zh:"教职员俱乐部", en:"Staff club"},
    d:{zh:"国大教职员俱乐部是教职员工用餐、聚会和交流的场所，设有餐厅和活动空间。它也常用来接待访客和举办小型聚会。",
       en:"The NUS Staff Club is a place for university staff to dine, meet and socialise, with a restaurant and event spaces. It is also often used to host visitors and small gatherings."}},
  "site:nus:UTown Residence": {k:{zh:"学生公寓", en:"Student residence"},
    d:{zh:"大学城研究生公寓为研究生和部分本科生提供住宿，设有公寓式房间和公共设施。住在这里可以步行到大学城的餐饮、学习和运动设施。",
       en:"UTown Residence houses graduate students and some undergraduates in apartment-style rooms with shared facilities. Residents are a short walk from University Town's food, study and sports facilities, and campus buses link it to the main Kent Ridge campus."}},
  "site:nus:NUS Link Bridge (over the AYE)": {k:{zh:"连接桥", en:"Link bridge"},
    d:{zh:"国大连接桥横跨亚逸拉惹快速公路（AYE），把肯特岗主校区与南边的大学城连在一起。师生可以步行或骑车在两个区域之间往来，校园巴士也从桥上经过。",
       en:"The NUS Link Bridge spans the Ayer Rajah Expressway (AYE), joining the main Kent Ridge campus with University Town to the south. Students and staff can walk or cycle between the two areas, and campus buses cross it too."}},
  "site:nus:University Town — Town Green": {k:{zh:"草坪", en:"Lawn"},
    d:{zh:"大学城绿地是大学城中央的一大片草坪，四周环绕着住宿书院和学习楼宇。学生在这里野餐、运动和举办户外活动，晚上也是看星星、聊天的好去处。",
       en:"Town Green is the big lawn at the heart of University Town, surrounded by residential colleges and study buildings. Students picnic, play sports and hold outdoor events here, and in the evening it is a nice place to chat under the sky."}},

  // Halls of residence
  "site:nus:Ridge View Residential College": {k:{zh:"住宿书院", en:"Residential college"},
    d:{zh:"岭景住宿学院位于肯特岗主校区，是大学城以外的住宿书院，书院课程与宿舍生活相结合。学生可以在这里体验书院式的学习，同时步行前往主校区的教学楼。",
       en:"Ridge View Residential College is on the main Kent Ridge campus rather than in University Town, combining college courses with residential life. Students get a college-style education while staying within walking distance of the main teaching buildings."}},
  "site:nus:Raffles Hall": {k:{zh:"学生舍堂", en:"Hall of residence"},
    d:{zh:"莱佛士舍堂是国大历史较悠久的学生舍堂之一，以新加坡开埠者莱佛士命名。舍堂以浓厚的集体生活、体育比赛和文艺演出传统著称。",
       en:"Raffles Hall is one of the older halls of residence at NUS, named after Stamford Raffles. It is known for its strong community spirit and its traditions of sports competitions and cultural performances."}},
  "site:nus:King Edward VII Hall": {k:{zh:"学生舍堂", en:"Hall of residence"},
    d:{zh:"英皇爱德华七世舍堂以爱德华七世医学院命名，传统可追溯到这所医学院当年的学生宿舍，是国大历史最悠久的舍堂之一。舍堂生活以运动、文艺和舍堂间的友好竞争为特色。",
       en:"King Edward VII Hall takes its name from the King Edward VII College of Medicine, and its traditions go back to that college's student hostel, making it one of the oldest halls at NUS. Hall life centres on sports, the arts and friendly rivalry with other halls."}},
  "site:nus:Prince George's Park Residences": {k:{zh:"学生宿舍", en:"Student residences"},
    d:{zh:"乔治王子公园宿舍位于校园边缘，是国大规模较大的学生宿舍区，由多座宿舍楼组成。宿舍与校园之间有校车往来，周边绿地环绕，环境安静。",
       en:"Prince George's Park Residences sits on the edge of the campus and is one of the larger NUS housing areas, made up of several residential blocks. Campus buses link it with the rest of the university, and it is surrounded by quiet greenery."}},
  "site:nus:Eusoff Hall": {k:{zh:"学生舍堂", en:"Hall of residence"},
    d:{zh:"尤索夫舍堂是国大的学生舍堂之一，位于肯特岗西侧的山坡上。和其他舍堂一样，这里有丰富的舍堂活动，学生通过运动队、文艺演出和社区服务结下深厚的情谊。",
       en:"Eusoff Hall is one of the NUS halls of residence, set on a slope on the western side of Kent Ridge. Like the other halls it has a busy hall life, and students build close friendships through sports teams, performances and community service."}},
  "site:nus:Kent Ridge Hall": {k:{zh:"学生舍堂", en:"Hall of residence"},
    d:{zh:"肯特岗舍堂以校区所在的肯特岗命名，是国大的学生舍堂之一。舍堂生活丰富多彩，学生在体育赛事、舍堂晚会和各类兴趣小组中相互认识、共同成长。",
       en:"Kent Ridge Hall is named after the ridge the campus stands on and is one of the NUS halls of residence. Hall life is full of activity, and students get to know each other through sports, hall nights and interest groups."}},
  "site:nus:Temasek Hall": {k:{zh:"学生舍堂", en:"Hall of residence"},
    d:{zh:"淡马锡舍堂以新加坡的古名“淡马锡”命名，是国大的学生舍堂之一，位于肯特岗西侧。舍堂重视集体生活，每年的舍堂间运动会和文艺演出都是重头戏。",
       en:"Temasek Hall is named after Temasek, an old name for Singapore, and is one of the NUS halls of residence on the western side of Kent Ridge. It values community life, and the yearly inter-hall games and performances are major highlights."}},
  "site:nus:Sheares Hall": {k:{zh:"学生舍堂", en:"Hall of residence"},
    d:{zh:"薛尔思舍堂以新加坡第二任总统薛尔思命名，他也是一位杰出的妇产科医生。舍堂位于肯特岗北坡，以活跃的舍堂文化和体育传统著称。",
       en:"Sheares Hall is named after Benjamin Sheares, Singapore's second President and a distinguished obstetrician. The hall sits on the northern slope of Kent Ridge and is known for its lively hall culture and sporting traditions."}},

  // ---------------- five more heroes (Marina Centre, Shenton Way, Bras Basah, Kampong Glam) ----------------
  sgmillenia: {k:{zh:"摩天大楼", en:"Skyscraper"}, y:"1996", h:218, fl:41, a:{zh:"凯文·洛奇", en:"Kevin Roche"},
    d:{zh:"美年大厦位于滨海中心淡马锡大道1号，紧邻宝门廊地铁站，1992年动工、1996年完工，高218米、41层，是美年城这组建筑里最高的一座。平面是正方形，立在四根会发光的圆柱上，每根约15米（50英尺），圆柱之间是五层高的玻璃大堂。塔身是浅色花岗石幕墙，窗格又密又齐，靠近顶部的四角收进一列深色玻璃。主屋面大约在176米，上面是一座约43米（140英尺）高的玻璃金字塔，金字塔上有一圈圈肋条。",
       en:"Millenia Tower, at 1 Temasek Avenue in Marina Centre beside Promenade MRT, was built from 1992 to 1996. At 218 metres and 41 storeys it is the tallest building in the Millenia Singapore development. The square plan stands on four lit cylinders, each about 15 metres (50 feet), around a glass lobby five storeys high. The shaft is a pale granite curtain wall with a tight window grid, and the top corners step back into dark glazing. The main roof is about 176 metres, under a ribbed glass pyramid about 43 metres (140 feet) tall."}},
  sgcentennial: {k:{zh:"摩天大楼", en:"Skyscraper"}, y:"1997", h:158, fl:37, a:{zh:"凯文·洛奇；2015年外立面由汤姆·梅恩重做", en:"Kevin Roche; facade reclad in 2015 by Thom Mayne"},
    d:{zh:"盛年大厦在淡马锡大道3号，与美年大厦、新达城相邻。1995年开工、1997年完工，高158米、37层。最初由凯文·洛奇设计，2015年由汤姆·梅恩更换了外立面：一格格互相咬合的窗框，越往上挑出越深。屋顶有一座约12米高的镂空格架，用来呼应旁边美年大厦的金字塔。结构上预留了往上加盖约15层的余地，但建成后一直是37层。1999年它获得建设局“最佳可施工设计奖”（商业与办公楼组别）。",
       en:"Centennial Tower stands at 3 Temasek Avenue, next to Millenia Tower and Suntec City. Started in 1995 and finished in 1997, it is 158 metres and 37 storeys. Kevin Roche designed it. In 2015 Thom Mayne reclad it with interlinking window frames that project further as they rise, and a 12 metre open trellis that answers Millenia's pyramid. The structure was built so that about 15 more storeys could be added later, but it has stayed at 37. In 1999 it won the Building and Construction Authority's Best Buildable Design Award for commercial and office buildings."}},
  sgcapital: {k:{zh:"摩天大楼", en:"Skyscraper"}, y:"2000", h:254, fl:52, a:{zh:"RSP建筑师规划与工程事务所", en:"RSP Architects Planners & Engineers"},
    d:{zh:"资金大厦在罗敏申路168号，丹戎巴葛地铁站旁边，2000年完工，屋顶高254米、52层，最高使用层大约在232米。2001年5月16日由时任国家发展部长马宝山主持揭幕。它原先计划作为邮政储蓄银行的总部，后来成为凯德的旗舰楼。平面是一个转过角度的长方形，北侧有个台阶形缺口。塔身是蓝绿玻璃，夹着浅色金属横档和暖色横带；朝向麦士威路的一面，中部有一道竖向玻璃槽和半圆形雨篷。靠近顶部有两道挑出的水平檐板，檐板以上角部变圆、塔身向内收，顶上是一圈圈水平百叶的玻璃塔冠，夜里会被照亮。52层由五部双层穿梭电梯服务；顶层是会员制的中国会，2001年5月19日开业。",
       en:"Capital Tower, 168 Robinson Road beside Tanjong Pagar MRT, was completed in 2000. The roof is 254 metres and there are 52 storeys; the highest occupied floor is about 232 metres. It was opened on 16 May 2001 by Mah Bow Tan, then Minister for National Development. Planned as the POSBank headquarters, it became CapitaLand's flagship. The plan is a rotated rectangle with a stepped notch on the north side. The shaft is blue-green glass with pale metal rails and warm horizontal bands. The face toward Maxwell Road has a vertical glass slot and a semicircular canopy. Two projecting cornices step the top, the corners round off and the shaft slopes in, and a louvered glass crown — lit at night — finishes the roof. Five double-deck shuttle lifts serve the floors. The members' China Club on the top floor opened on 19 May 2001."}},
  sgsota: {k:{zh:"艺术学校", en:"Arts school"}, y:"2010", h:50, a:{zh:"WOHA建筑事务所", en:"WOHA"},
    d:{zh:"新加坡艺术学院是一所六年制艺术专科学校，2008年1月2日开办，2010年1月迁入布拉斯巴沙、索菲亚山脚的朱比萨伊路1号新校舍。校舍由WOHA设计：地面层架空，底部包着深色折叠金属，上面是三座白色框架的长条楼。每座长向立面一半是密排的竖向鳍片，一半是垂直绿化，楼与楼之间有天桥。地图上这座建筑标高约50米。",
       en:"School of the Arts is a six-year specialised arts school. It opened on 2 January 2008 and moved in January 2010 into its campus at 1 Zubir Said Drive, Bras Basah, at the foot of Mount Sophia. WOHA designed it with an open ground floor, a dark folded-metal base, and three white-framed bars. Each long face is half dense vertical fins and half a planted wall, and a skybridge links the bars. The mapped height of this block is about 50 metres."}},
  sgmalabar: {k:{zh:"清真寺", en:"Mosque"}, y:"1963", a:{zh:"A.H. Siddique", en:"A.H. Siddique"},
    d:{zh:"马拉巴回教堂在甘榜格南，维多利亚街471号与苏丹街的路口，1963年1月24日由总统尤索夫·伊沙克主持启用，南印度马拉巴穆斯林社群出资，又叫“蓝清真寺”。建筑师是A.H. Siddique，平面斜向麦加，礼拜大殿在二楼，三面有游廊。外墙原先是油漆，1995年翻新时改贴浅蓝与白色的几何瓷砖。中央是一座坐在鼓座上的金色洋葱顶，一侧有较小的金顶，另一侧是八角宣礼塔，塔顶同样是小金顶和新月。",
       en:"The Malabar Mosque, also called the Blue Mosque, stands at 471 Victoria Street where it meets Jalan Sultan in Kampong Glam. President Yusof Ishak opened it on 24 January 1963 for the Malabar Muslim community. A.H. Siddique designed it with the plan set toward Mecca; the prayer hall is on the upper floor, with verandas on three sides. The walls were painted until the 1995 renovation, which added light turquoise and white geometric tiles. A gold onion dome sits on a drum, with a smaller dome to one side and an octagonal minaret, itself capped by a small gold dome and crescent, to the other."}}
});
